UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Wandel in een tempo waarbij je hartslag merkbaar omhooggaat, maar je nog gewoon een gesprek kunt voeren","Zwaai je armen actief mee en zet stevige passen — geen slenteren, maar doelbewust doorstappen","Houd deze inspanning de hele duur vol zonder te stoppen"]'), '$.cues_nl', json('["💡 Stevig wandelen in zone 2 traint je hart en longen en belast je gewrichten nauwelijks","Ideaal om mee te beginnen, of als actief herstel voor getrainde sporters"]')), updated_at_ms = 1795305600000 WHERE slug = 'brisk-walk' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Walk at a pace that noticeably elevates your heart rate but still allows full conversation.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Wandel in een rustig, ontspannen tempo — stop niet abrupt na een zware inspanning","Laat je hartslag in 5 minuten vanzelf zakken","Let op een langzame, diepe ademhaling: adem in door je neus en uit door je mond","Schud je benen rustig los en voel hoe ze aanvoelen — handige informatie voor je volgende training"]'), '$.cues_nl', json('["💡 Abrupt stoppen na een maximale inspanning kan je duizelig maken — blijf bewegen","Op wandeltempo hoort je hartslag binnen 2–3 minuten onder de 120 slagen per minuut te zakken"]')), updated_at_ms = 1795305600000 WHERE slug = 'cooldown-walk' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Walk at a comfortable, relaxed pace — do not stop abruptly after an intensive effort';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Verhoog de weerstand tot het voelt als een helling van 6–10%. Verlaag je trapfrequentie naar 60–75 rpm","Trap met kracht door — zwaardere weerstand, zittend. Je kunt ook afwisselen tussen zitten en staan","Klim 5–10 minuten en verlaag dan de weerstand om 3 minuten rustig te trappen. Herhaal"]'), '$.cues_nl', json('["💡 Klimmen bouwt kracht en spieruithoudingsvermogen tegelijk op","Buiten op de racefiets: kies een echte heuvel en rijd in tempo-inspanning naar de top"]')), updated_at_ms = 1795305600000 WHERE slug = 'cycling-hill-climb' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Increase resistance to simulate a 6–10% gradient. Reduce cadence to 60–75 rpm.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Doe een warming-up van 5 minuten op 70–90 W en 80 rpm — je hartslag hoort op 110–120 slagen per minuut te zitten voordat de intervallen beginnen","Inspanningsinterval: verhoog de weerstand tot het maximale vermogen dat je kunt volhouden. Mik op 150–250 W bij 90–110 rpm. Dit voelt als een 8–9 op 10 — streefhartslag 160–175 slagen per minuut","Herstelinterval: zak terug naar 60–90 W bij 70–80 rpm. Laat je hartslag dalen tot 120–130 slagen per minuut voordat de volgende inspanning begint. Volledig herstel maakt HIIT effectief","Herhaal het patroon van inspanning en herstel. Laatste 5 minuten: cooling-down op 60–80 W en 75 rpm"]'), '$.cues_nl', json('["💡 Wattages: beginners 120–160 W inspanning / 60–80 W herstel. Gemiddeld 160–220 W / 70–90 W. Gevorderd 200–280 W of meer / 80–100 W","💡 Trapfrequentie tijdens de inspanning: 90–110 omwentelingen per minuut. Een hoge trapfrequentie prikkelt hart en longen maximaal","💡 HIIT op de fiets is vriendelijk voor je gewrichten — je kunt harder gaan dan bij loopintervallen, met minder kans op blessures","💡 Een hartslag van 165–175 slagen per minuut tijdens de inspanning is het doel. Haal je de 160 niet, verhoog dan de weerstand"]')), updated_at_ms = 1795305600000 WHERE slug = 'cycling-intervals-indoor' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Warm up at 70–90W for 5 minutes at 80 RPM — HR should reach 110–120 bpm before the intervals begin.';
