UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Bouw na 5 minuten warming-up de intervallen op als een piramide: 1 min hard / 1 min rustig, 2 min hard / 2 min rustig, 3 min hard / 3 min rustig, en dan weer terug: 2 min hard / 2 min rustig, 1 min hard","Harde intervallen op 90–95% inspanning. Rustige intervallen echt rustig","Fiets 5 minuten rustig uit"]'), '$.cues_nl', json('["💡 De piramide-opbouw zorgt voor afwisseling in duur en intensiteit binnen één training","Let bij elke trede van de piramide op je inspanning en probeer steeds dezelfde gevoelsinspanning vast te houden"]')), updated_at_ms = 1795305600000 WHERE slug = 'cycling-pyramid-effort' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'After a 5-minute warm-up, build intervals in a pyramid: 1 min hard / 1 min easy, 2 min hard / 2 min easy, 3 min hard / 3 min easy, then back down: 2 min hard / 2 min easy, 1 min hard.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Doe een warming-up van 5–8 minuten rustig trappen. Kom op een trapfrequentie van 90 rpm of hoger","Sprint 10–20 seconden voluit — maximale inspanning, maximale trapfrequentie","Herstel 90–120 seconden met rustig trappen. Herhaal 6–10 keer"]'), '$.cues_nl', json('["💡 Korte sprints trainen je piekvermogen — de inspanning moet maximaal zijn, anders mis je het trainingseffect","Ga op een hometrainer op de pedalen staan voor de sprint; blijf op een smart trainer zitten"]')), updated_at_ms = 1795305600000 WHERE slug = 'cycling-sprint-intervals' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Warm up 5–8 minutes easy spinning. Reach 90+ rpm cadence.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Mik op 88–93% van je FTP (of op gevoel: 7–7,5 op 10). Zwaarder dan tempo, lichter dan VO2 max","Houd deze ''sweet spot''-inspanning vast in blokken van 10–20 minuten, met 5 minuten rustig trappen tussen de blokken","Trapfrequentie: 85–95 rpm. Sluit af met 5 minuten rustig uitfietsen"]'), '$.cues_nl', json('["💡 Sweet spot levert 80% van het trainingseffect van volle drempeltraining op voor 60% van de herstelkosten","Je ademt zwaar maar ritmisch — een woord of twee lukt, hele zinnen niet"]')), updated_at_ms = 1795305600000 WHERE slug = 'cycling-sweet-spot' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Target 88–93% of FTP (or perceived effort: 7–7.5 out of 10). Harder than tempo, easier than VO2 max.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zoek na 5 minuten rustig infietsen een inspanning op die ''stevig maar vol te houden'' voelt — ongeveer 75–85% van je FTP of een 7 op 10","Houd dit tempo 15–30 minuten vast en fiets daarna 5 minuten rustig uit","Adem ritmisch en let op je trapfrequentie (mik op 85–95 rpm)"]'), '$.cues_nl', json('["💡 Tempo = je kunt 2–3 woorden zeggen, geen hele zinnen","Let op een soepele, krachtige pedaalslag — geen dode punten boven of onder"]')), updated_at_ms = 1795305600000 WHERE slug = 'cycling-tempo-effort' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'After a 5-minute easy spin warm-up, settle into a ''comfortably hard'' effort — about 75–85% FTP or 7 out of 10 perceived effort.';
