UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Jog in een heel rustig tempo waarbij je kunt praten — alleen zone 1 (je kunt een heel gesprek voeren)","Houd je ademhaling ontspannen, loop rechtop en kijk vooruit","Dit is voorbereiding, geen training — ga meteen wandelen als je buiten adem raakt","Na 7 minuten voel je je warm en los, niet buiten adem"]'), '$.cues_nl', json('["💡 Zone 1 betekent dat je zonder moeite hele zinnen kunt zeggen — lukt dat niet, ga dan langzamer","Gebruik deze tijd om in gedachten je tempoverdeling voor de inspanning straks door te nemen"]')), updated_at_ms = 1795305600000 WHERE slug = 'easy-jog-warmup' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Jog at a very easy, conversational pace — Zone 1 only (you could hold a full conversation)';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Start running outdoors at about 7.5 km/h, an easy pace","Adjust your pace until your heart rate settles at 125–135 bpm — this is Zone 2, your aerobic base pace","Stay within 7–9 km/h (6:40–8:30 min/km); your exact Zone 2 speed depends on fitness, so let heart rate be your guide","If your heart rate goes above 135 bpm, slow down by 0.3–0.5 km/h and hold that pace — this is precise Zone 2 training, not failure"]'), '$.cues', json('["💡 Talk test: say a full sentence without gasping. If you cannot, you have left Zone 2 — slow down","💡 Uphill or into the wind your heart rate climbs at the same speed — slow down and let heart rate decide, not pace","💡 Reference range for moderate-fitness runners in Zone 2: 7.5–8.5 km/h","💡 Zone 2 builds your aerobic engine. Slower than it feels right is usually correct on easy days."]'), '$.steps_nl', json('["Begin buiten te lopen op ongeveer 7,5 km/u, een rustig tempo","Pas je tempo aan tot je hartslag rond de 125–135 slagen per minuut blijft — dit is zone 2, je aerobe basistempo","Blijf tussen 7 en 9 km/u (6:40–8:30 min/km); je exacte zone 2-tempo hangt af van je conditie, dus laat je hartslag leidend zijn","Komt je hartslag boven de 135, ga dan 0,3–0,5 km/u langzamer en houd dat vast — dat is geen falen, maar precies trainen in zone 2"]'), '$.cues_nl', json('["💡 Praattest: zeg een hele zin zonder naar adem te happen. Lukt dat niet, dan zit je boven zone 2 — ga langzamer","💡 Heuvelop of met tegenwind stijgt je hartslag bij dezelfde snelheid — ga langzamer en laat je hartslag beslissen, niet je tempo","💡 Richtwaarde voor lopers met een gemiddelde conditie in zone 2: 7,5–8,5 km/u","💡 Zone 2 bouwt je aerobe motor op. Op rustige dagen is langzamer dan goed voelt meestal precies goed"]')), updated_at_ms = 1795305600000 WHERE slug = 'easy-run-outdoor' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_