UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop en zet dan je handen op de vloer","Loop met je voeten naar achteren tot je in een plank staat","Loop met je voeten terug naar je handen","Kom overeind — zonder te springen"]'), '$.cues_nl', json('["Een beweging voor je hele lichaam, zonder de impact","Je kunt ook voet voor voet stappen","Mooie opstap naar de volledige burpee"]')), updated_at_ms = 1795305600000 WHERE slug = 'modified-burpee' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand, then place hands on floor';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Kies een route met duidelijke sprintstukken — vlakke rechte stukken of gelijkmatige klimmen van 2–4 minuten. Fiets je 10 minuten warm in een rustig tempo (hartslag onder 125, 80 RPM)","Inspanningsinterval: sprint op 85–95% inspanning. Richtsnelheid op vlak terrein: 30–45 km/u. Vermogensmeter: 85–100% van je FTP. Sprint staand op klimmen en zittend op het vlakke. Richthartslag: 165–178 bpm","Herstel: trap rustig door op 15–22 km/u, 70–80 RPM. Laat je hartslag onder 130 zakken voor de volgende inspanning. Blijf trappen tijdens het herstel","Herhaal het patroon van inspanning en herstel de hele sessie. Laatste 10 minuten: rustig uitfietsen als cooling-down"]'), '$.cues_nl', json('["💡 Richtwaarden vermogensmeter: inspanning 85–100% FTP (bijv. 170–200 W bij een FTP van 200 W). Herstel 40–55% FTP","💡 Cadans in sprints: vlakke sprints 90–110 RPM, klimmen 75–90 RPM. Stem je cadans af op het terrein","💡 HIIT buiten: het terrein geeft natuurlijke weerstand — heuvels en tegenwind zorgen voor wisselende, effectieve belasting","💡 Doe een volledige warming-up voor de eerste inspanning. Buiten (kou, wind) hebben je spieren meer voorbereiding nodig"]')), updated_at_ms = 1795305600000 WHERE slug = 'outdoor-bike-hiit' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Choose a route with clear sprint sections — flat straights or consistent climbs of 2–4 minutes. Warm up at easy pace for 10 minutes (HR below 125, 80 RPM).';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Kies een vlakke tot licht glooiende route. Kom binnen de eerste 10 minuten in zone 2: hartslag 125–135 bpm, cadans 80–90 RPM","Richtsnelheid op vlak terrein: 20–28 km/u. Heb je een vermogensmeter, houd dan 50–65% van je FTP (Functional Threshold Power) aan. Beide zijn kenmerken van zone 2","Klimmen: schakel terug en houd je cadans vast (80–90 RPM) in plaats van zwaar te stampen. Komt je hartslag op een klim boven 138 bpm, accepteer dan een lagere snelheid — je hartslag bepaalt","Afdalingen: herstel actief. Laat je hartslag op lange afdalingen zakken richting 120 bpm en pak op het vlakke je zone 2-inspanning weer op"]'), '$.cues_nl', json('["💡 Praattest bij 25 km/u: kun je niet meer in korte zinnen praten, dan zit je boven zone 2 — trap wat minder hard","💡 Een cadans van 80–90 RPM is efficiënter dan zwaar trappen op 60–70 RPM bij hetzelfde wattage","💡 Rijd je met een vermogensmeter: zone 2 = 55–75% FTP (bijv. bij een FTP van 200 W is zone 2 110–150 W)","💡 Zone 2 buiten: wisselend terrein is prima — stuur op je hartslag om op heuvels en vlakke stukken in je zone te blijven"]')), updated_at_ms = 1795305600000 WHERE slug = 'outdoor-bike-zone2' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Choose a flat-to-gently-rolling route. Settle into Zone 2 within the first 10 minutes: HR 125–135 bpm, cadence 80–90 RPM.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop. Stap met je rechtervoet naar achteren in een achterwaartse uitvalspas en laat je achterste knie richting de vloer zakken","Duw door je linkervoet om op te staan, breng direct je rechterknie omhoog en strek je been uit in een voorwaartse trap","Zet je rechtervoet weer neer en herhaal. Wissel van been na je herhalingen"]'), '$.cues_nl', json('["💡 De trap is gecontroleerd, geen wilde zwiep — span bovenaan je bovenbeenspier aan","Je standbeen werkt hard — dit is net zo goed een oefening voor coördinatie en kracht als voor cardio"]')), updated_at_ms = 1795305600000 WHERE slug = 'reverse-lunge-kick' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall. Step your right foot back into a reverse lunge, lowering your rear knee toward the floor.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Stel de monitor in op 2000 meter roeien. Roei je 5 minuten rustig warm en bouw op naar een gemiddeld tempo","Roei de volledige 2 km op de maximale inspanning die je kunt volhouden. Start op je doeltempo, houd dat vast in het middenstuk en versnel in de laatste 500 m","Roei na de finish 5 minuten rustig uit om te herstellen — je hartslag is dan hoog"]'), '$.cues_nl', json('["💡 Negative split: roei van 1000 tot 1500 m beheerst en bouw vanaf 1500 m op","Noteer je splittijd en gebruik die als ijkpunt voor volgende sessies"]')), updated_at_ms = 1795305600000 WHERE slug = 'rowing-2k-time-trial' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Set the monitor to row 2000 metres. Warm up 5 minutes easy, building to a moderate pace.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Roei je 3–5 minuten warm in een rustig tempo: 24–26 SPM, split rond 2:35–2:45 /500 m, hartslag onder 130","Inspanningsinterval: zet krachtig af voor de opgegeven duur. Richtsplit: onder 2:10 /500 m bij 24–28 SPM. Dit is bijna maximale inspanning — richthartslag 165–175 bpm","Herstelinterval: zak naar 18–20 SPM op 2:40–2:50 /500 m. Laat je hartslag onder 130 zakken voor de volgende inspanning. Actief herstel — blijf roeien, stop niet","Herhaal het patroon van inspanning en herstel de hele sessie"]'), '$.cues_nl', json('["💡 Richtsplits voor HIIT op de roeier: beginners onder 2:20 /500 m, gemiddeld onder 2:10, gevorderd onder 2:00","💡 SPM tijdens inspanningen: 24–28 halen per minuut. Verhoog je kracht, niet je SPM, om je richtsplit te halen","💡 De kracht begint bij de inpik: armen gestrekt, schenen verticaal, gewicht naar voren — daarna zetten je benen af","💡 HIIT op de roeier hoort bij de HIIT-vormen met het hoogste calorieverbruik — 800–1000 kcal/uur bij maximale inspanning"]')), updated_at_ms = 1795305600000 WHERE slug = 'rowing-intervals' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Warm up with 3–5 minutes at easy pace: 24–26 SPM, split around 2:35–2:45 /500m, HR below 130.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Roei 3 minuten rustig als warming-up. Doe daarna binnen elke minuut 10 halen op maximale kracht en roei de rest van de minuut rustig","De 10 krachthalen moeten explosief zijn — duw je split duidelijk lager dan normaal","Herhaal deze cyclus van 1 minuut 10 minuten lang. Roei 2 minuten rustig uit als cooling-down"]'), '$.cues_nl', json('["💡 Tel de 10 halen zorgvuldig — ga na 10 direct terug naar rustig roeien","Hiermee ontwikkel je pure kracht zonder dat de vermoeidheid te veel oploopt"]')), updated_at_ms = 1795305600000 WHERE slug = 'rowing-power-strokes' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Row easy for 3 minutes as a warm-up. Then, within each minute, perform 10 strokes at maximum power followed by the rest of the minute easy.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Roei 3 minuten rustig warm. Roei zware intervallen in een piramide: 30 s / 60 s / 90 s / 2 min / 90 s / 60 s / 30 s","De rust tussen de intervallen is even lang als het interval zelf. Roei de zware intervallen op bijna maximale inspanning","Roei 3 minuten rustig uit als cooling-down"]'), '$.cues_nl', json('["💡 De piek van 2 minuten is het zwaarst — doseer op weg omhoog, zodat je die kunt volhouden","Houd de volgorde van de haal ook op hoge intensiteit correct: benen → rug → armen"]')), updated_at_ms = 1795305600000 WHERE slug = 'rowing-pyramid-intervals' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Warm up 3 minutes easy. Row hard intervals in a pyramid: 30s / 60s / 90s / 2 min / 90s / 60s / 30s.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Stel de weerstand zo in dat je 18–20 halen per minuut (SPM) volhoudt op een comfortabele, constante inspanning","Richtsplit: 2:20–2:40 per 500 m. Dit is roeien in zone 2 — je hartslag hoort binnen 5 minuten uit te komen op 125–135 bpm","Houd dit tempo de hele sessie vast. Komt je hartslag boven 135, verlaag dan je haalfrequentie met 1–2 SPM of zet minder krachtig af","Let op de volgorde inpik, haal, uitpik, herstel: eerst je benen, dan achteroverleunen, dan trekken je armen naar je onderborst"]'), '$.cues_nl', json('["💡 De praattest werkt ook op de roeier — in zone 2 moet je hele zinnen kunnen zeggen","💡 Richtsplit: 2:25–2:35 /500 m is de gangbare zone 2-referentie voor recreatieve roeiers","💡 18–20 SPM: een lagere haalfrequentie dwingt je tot langere, krachtigere halen — zo bouw je aerobe efficiëntie op","💡 Roeien in zone 2 is aeroob werk voor je hele lichaam: benen (60%), core (20%), armen (20%) bij elke haal"]')), updated_at_ms = 1795305600000 WHERE slug = 'rowing-steady-state' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Set resistance so you maintain 18–20 strokes per minute (SPM) at a comfortable, sustained effort.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Roei heel langzaam (16–18 SPM) en met weinig druk, en let volledig op de volgorde: BENEN → RUG → ARMEN (haal), daarna ARMEN → RUG → BENEN (herstel)","Pauzeer op drie punten: alleen armen bij de uitpik, halverwege de slide en bij de inpik (schenen verticaal)","Controleer na elke pauze je houding voordat je naar het volgende deel gaat"]'), '$.cues_nl', json('["💡 Een goede volgorde op lage snelheid wordt op wedstrijdtempo een automatisme","Dit gaat NIET om een cardiotraining — de kwaliteit van je beweging is het enige dat telt"]')), updated_at_ms = 1795305600000 WHERE slug = 'rowing-technique-drill' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Row at a very slow rate (16–18 spm) and low pressure, focusing entirely on sequence: LEGS → BACK → ARMS (drive), then ARMS → BACK → LEGS (recovery).';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Stel je richtsplit in op een tempo waarbij je kunt blijven praten — ongeveer 2:20–2:40 /500 m voor beginners, 2:00–2:20 voor gemiddelde roeiers","Roei met 18–20 halen per minuut. Let erop dat je split constant blijft en niet verloopt","Houd dit de hele duur vol. Sluit af met 2 minuten rustig uitroeien"]'), '$.cues_nl', json('["💡 Roeien in zone 2 is bijzonder effectief om met je hele lichaam een aerobe basis op te bouwen","Controleer elke 5 minuten of je split niet is opgelopen — is dat zo, dan is het vermoeidheid: pas aan"]')), updated_at_ms = 1795305600000 WHERE slug = 'rowing-zone2' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Set your target split at a pace you can maintain conversationally — about 2:20–2:40 /500 m for beginners, 2:00–2:20 for intermediate.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Begin de eerste 5 minuten in een voorzichtig tempo (hartslag 120–125) en laat het daarna uitkomen in je zone 2-bereik (125–135 bpm)","Bij 35 minuten in zone 2 telt je tempo-indeling: begin rustig, zodat de tweede helft aeroob blijft","Richttempo: 6:30–8:30 min/km (7–9 km/u) op vlak terrein. Heuvels: verlaag je tempo om je hartslag onder 135 te houden","Laatste 5 minuten: controleer je techniek — ontspannen schouders, stille voetlanding, natuurlijke armzwaai. Dit is je aerobe basis aan het werk"]'), '$.cues_nl', json('["💡 Een hartslag van 130 bpm is je doel. Onder 125 = te makkelijk, boven 135 = te zwaar","💡 Richtwaarde loopband: 8 km/u met 1% helling. Pas aan met ±0,5 km/u om in je hartslagzone te komen","💡 Vanaf 35 minuten gaat eten en drinken meetellen: drink voldoende voor lange zone 2-lopen","💡 Zone 2 van deze duur verbetert je vetverbranding en loopefficiëntie aanzienlijk"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-10' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Start at a conservative pace (HR 120–125) for the first 5 minutes, then let it settle to your Zone 2 band (125–135 bpm).';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop je 5 minuten warm in een heel rustig tempo (hartslag onder 120) en kom daarna in zone 2 (hartslag 125–135)","40 minuten in zone 2 — richttempo 6:30–8:30 min/km (7–9 km/u) op vlak terrein. Gebruik je hartslag als enige echte leidraad","Controle halverwege (20 min): praat je nog makkelijk? Mooi. Voelt het alsof je nog veel over hebt? Mooi. Dat is zone 2","Cooling-down: in de laatste 5 minuten wordt het vanzelf lichter, omdat je tempo gelijk blijft maar de inspanning afneemt — hier begint de trainingsaanpassing"]'), '$.cues_nl', json('["💡 Hartslag in zone 2: de hele tijd 125–135 bpm. Loopband: begin op 8 km/u met 1% helling","💡 Na 40 minuten loopt je lichaam vooral op vet als brandstof — efficiënt en lang vol te houden","💡 Deze sessie levert voor je aerobe ontwikkeling meer op dan 20 minuten harder lopen","💡 Loopt je hartslag in de tweede helft op tot boven 135, verlaag dan je tempo met 10 sec/km — geen mislukking, maar een bijsturing"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-11' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Warm up at very easy pace (HR below 120) for 5 minutes, then settle into Zone 2 (HR 125–135).';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 45 minuten in zone 2. Gebruik de eerste 10 minuten als warming-up binnen de zone (hartslag 120–128) en blijf daarna rond 130","Tempo: 6:30–8:30 min/km (7–9 km/u) op vlak terrein. Op de loopband: 7,5–8,5 km/u met 1% helling","Strategie: verdeel de loop in gedachten in drie blokken van 15 minuten. Elk blok: inkomen, vasthouden, afmaken. Houd je hartslag in alle drie gelijk","De laatste 5 minuten horen hetzelfde te voelen als minuut 10 — dan doet je aerobe basis zijn werk"]'), '$.cues_nl', json('["💡 Hartslag 130 bpm. Kun je na ruim 40 minuten nog steeds praten, dan ben je aeroob gebleven — goed gedaan","💡 Loopband: 8 km/u met 1% helling is de gangbare zone 2-referentie voor de meeste lopers met een gemiddelde conditie","💡 45 minuten zone 2 per sessie is het trainingsvolume dat samenhangt met een duidelijke stijging van je VO2max","💡 Voeding: eet bij lopen van meer dan 40 minuten 2 uur van tevoren een kleine koolhydraatrijke snack"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-12' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '45 minutes of Zone 2. Treat the first 10 minutes as a warm-up within the zone (HR 120–128), then settle at 130.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 50 minuten in zone 2. Drink vooraf genoeg — bij deze duur beïnvloedt een vochttekort bij de start je hartslag en je prestatie","Kom binnen de eerste 8 minuten uit op een hartslag van 125–135 bpm. Tempo: 6:30–8:30 min/km (7–9 km/u) op vlak terrein","Check halverwege (25 min): is je hartslag stabiel? Adem je rustig? Is je hartslag opgelopen tot 140 of hoger, dan ben je te hard gegaan — loop 15 sec/km langzamer","Eindig sterk in techniek, niet in tempo. Schouders, pas, ademhaling — alles ontspannen"]'), '$.cues_nl', json('["💡 50 minuten op hartslag 130 is een flinke aerobe trainingsprikkel — effectiever dan 25 minuten op hartslag 155","💡 Loopband: 7,5–8,5 km/u met 1% helling. Pas aan met ±0,3 km/u om binnen je hartslagzone te blijven","💡 Cardiale drift is normaal: je hartslag kan in de loop van de sessie 3–5 bpm stijgen bij gelijk tempo","💡 Je zone 2-tempo wordt bij dit volume 20–30 sec/km sneller over een trainingsblok van 12 weken"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-13' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '50-minute Zone 2 run. Hydrate beforehand — at this duration, starting dehydrated affects HR and performance.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 55 minuten in zone 2. Kies een route of loopbandinstelling die je zonder onderbreking volhoudt — aan één stuk lopen geeft meer aerobe prikkel dan stoppen en starten","Doel: de hele loop een hartslag van 125–135 bpm. Tempo: 6:30–8:30 min/km (7–9 km/u). Op de loopband is 8 km/u met 1% helling je startpunt","Check na 30 minuten: is je hartslag stabiel? Loop je soepel? Voelt de inspanning hetzelfde als in minuut 10, dan doet je aerobe basis zijn werk","Laatste 10 minuten: houd je techniek vast. Stille voeten, ontspannen armen, rechte houding. Hier verdien je het trainingseffect"]'), '$.cues_nl', json('["💡 Hartslag 130 is de gulden middenweg — genoeg prikkel om je basis op te bouwen, laag genoeg om binnen 24 uur volledig te herstellen","💡 Eén duurloop van 55 minuten in zone 2 = meer aerobe winst dan twee lopen van 25 minuten op gemiddelde inspanning","💡 Loopband: 1% helling compenseert het ontbreken van luchtweerstand — loop nooit vlak op een loopband","💡 Na deze loop hoor je het gevoel te hebben dat je nog 15 minuten door kunt. Dat klopt"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-14' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '55-minute Zone 2 run. Choose a route or treadmill setting you can sustain without interruption — continuous running delivers more aerobic stimulus than stop-start.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 60 minuten in zone 2 — een vol uur. Drink vooraf goed. Neem water mee als het warmer is dan 15 °C","Kom binnen de eerste 8 minuten uit op een hartslag van 125–135 bpm. Tempo: 6:30–8:30 min/km (7–9 km/u). Loopband: 8 km/u met 1% helling als startpunt","Verdeel de loop in vier blokken van 15 minuten. Blok 1: inkomen. Blok 2: je ritme vinden. Blok 3: omgaan met vermoeidheid. Blok 4: bewust afmaken","Na 45 minuten telt je hoofd net zo zwaar als je conditie. Blijf erbij — één kilometer tegelijk"]'), '$.cues_nl', json('["💡 60 minuten op hartslag 130 is een van de meest effectieve aerobe trainingen die je in één sessie kunt doen","💡 Cardiale drift: je hartslag kan in de laatste 20 minuten 5 bpm stijgen bij gelijk tempo — dat is normaal","💡 Een uur hardlopen in zone 2 verhoogt je VO2max duidelijk over een trainingscyclus","💡 Eet 2 uur voor een loop van deze duur een kleine koolhydraatrijke snack (banaan, havermout)"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-15' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '60-minute Zone 2 run — one full hour. Hydrate properly beforehand. Carry water if temperature is above 15°C.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 75 minuten in zone 2. Dit is een serieuze lange duurloop — plan je route, neem water mee en eet 2 uur vooraf een koolhydraatrijke snack","Doelhartslag: 125–135 bpm. Tempo: 6:30–8:30 min/km. Op de loopband: 8 km/u met 1% helling, pas aan met ±0,5 om in je zone te blijven","Bij lopen van meer dan 60 minuten moet je de hartslagdrift in de gaten houden: stijgt je hartslag na 45 minuten boven 135, loop dan langzamer — niet doorduwen","Laatste 15 minuten: controleer actief je techniek. Vermoeidheid zie je het eerst aan je houding — je schouders zakken, je pas wordt korter. Corrigeer dat bewust"]'), '$.cues_nl', json('["💡 Hartslag 130 × 75 minuten = maximale gepolariseerde trainingsprikkel zonder grote herstelschuld","💡 Vet is in zone 2 je belangrijkste brandstof. Je glycogeenvoorraad gaat op deze intensiteit ruim 90 minuten mee — de meeste lopers hoeven onderweg niets te eten","💡 Loopband bij deze duur: check de ventilator, houd een bidon binnen handbereik en accepteer dat het mentaal zwaar is","💡 Na deze loop haal je met 36 uur rustige activiteit het meeste uit de aerobe aanpassing"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-16' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '75-minute Zone 2 run. This is a serious long run — plan your route, carry water, and eat a carbohydrate snack 2 hours before.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 90 minuten in zone 2. Eet en drink voordat je begint — bij 90 minuten raakt bij sommige lopers zelfs in zone 2 de glycogeenvoorraad leeg","Houd de hele loop een hartslag van 125–135 bpm aan. Tempo: 6:30–8:30 min/km. Na 60 minuten moet je misschien 10–15 sec/km langzamer lopen voor dezelfde hartslag — dat klopt, het is geen falen","Mentale strategie: verdeel de loop in drie delen van 30 minuten. Elk deel heeft zijn eigen uitdaging: opwarmen, opbouwen, vasthouden. In de laatste 30 minuten bouw je uithoudingsvermogen op","Laatste 10 minuten: actieve cooling-down binnen de loop — zelfde tempo, bewust de inspanning loslaten"]'), '$.cues_nl', json('["💡 Cardiale drift kan na 90 minuten 8–10 bpm aan je hartslag toevoegen bij gelijk tempo — ga langzamer lopen, niet doorduwen","💡 Heb je hardloopgels of -blokjes, dan helpt er één na 60 minuten om in zone 2 te blijven zonder de man met de hamer tegen te komen","💡 90 minuten in zone 2 is de ruggengraat van de training van afstandslopers — hier wordt je marathontempo op gebouwd","💡 Herstel: morgen een volledige rustdag, of alleen heel lichte mobiliteit"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-17' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '90-minute Zone 2 run. Fuel and hydrate before you start — at 90 minutes, even Zone 2 depletes glycogen stores in some runners.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 105 minuten in zone 2. Verplichte voorbereiding: drink de dag ervoor genoeg, eet een goede koolhydraatrijke maaltijd en neem water mee of plan een waterstop","Hartslag 125–135 bpm. Tempo: 6:30–8:30 min/km. Reken erop dat je houdbare tempo 15–20 sec/km lager ligt dan bij je kortere lopen — dat is normaal bij deze duur","Eerste 20 minuten: weersta de neiging om harder te lopen dan hartslag 130. In de laatste 40 minuten ben je er blij om","Vanaf 75 minuten: loop puur op je aerobe systeem. Hartslag stabiel, aandacht bij je techniek"]'), '$.cues_nl', json('["💡 Met 1 uur en 45 minuten is dit een echte lange duurloop. Je tempo doet er niet toe — de tijd die je in zone 2 op de been bent wel","💡 Eet na 60 en na 90 minuten: 25–35 g snelle koolhydraten (gel, banaan, dadels)","💡 Na deze loop 48 uur actief herstel — geen HIIT, geen krachttraining. Geef de aerobe aanpassing de tijd","💡 Hier bouw je je aerobe motor. Het ongemak is het signaal"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-18' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '105-minute Zone 2 run. Mandatory preparation: hydrate the day before, eat a proper carbohydrate meal, carry water or plan a water stop.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 120 minuten in zone 2. Volledige voorbereiding is nodig: drink vanaf 24 uur vooraf genoeg, eet ''s ochtends koolhydraten en neem drinken mee of plan het in","De hele loop een hartslag van 125–135 bpm. In de laatste 30 minuten ligt je tempo vanzelf 20–25 sec/km lager dan bij je kortere zone 2-lopen — houd je hartslag vast, niet je tempo","Eerste 30 minuten: gedisciplineerd geduld. Je benen willen harder. Geef niet toe — je bouwt een aerobe motor","Laatste 30 minuten: dit zijn de waardevolste minuten van de hele sessie. Blijf erbij, houd je techniek vast en maak de loop af"]'), '$.cues_nl', json('["💡 2 uur in zone 2 is dé lange duurloop in de voorbereiding op een halve marathon","💡 Voedingsstrategie: 30–40 g koolhydraten na 45 en na 90 minuten. Drink elke 20 minuten","💡 Je vetverbranding wordt het sterkst efficiënter door lopen van meer dan 90 minuten in zone 2","💡 Na de loop: eiwitten + koolhydraten binnen 30 minuten, morgen een volledige rustdag"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-19' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '120-minute Zone 2 run. Full preparation required: hydrate 24 hours before, eat carbohydrates the morning of, carry or plan for fluids.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 150 minuten in zone 2. Dit is een serieuze sportieve onderneming — behandel het als een trainingsevenement, niet als zomaar een loop","Hartslag 125–133 bpm. Reken erop dat je tempo in de tweede helft flink terugloopt — dat klopt. Laat je volledig leiden door je hartslag","Voeding is nodig: eet elke 45 minuten 30–40 g koolhydraten (gel, banaan, reep). Drink elke 20 minuten","Laatste 30 minuten: de vermoeidheid is echt. Richt je volledig op je techniek — stille voeten, rechte houding, ontspannen handen. De aerobe aanpassing gebeurt nu"]'), '$.cues_nl', json('["💡 2,5 uur in zone 2 komt in de buurt van de lange duurloop voor een marathon — weinig niet-sporters proberen dit. Je bouwt iets groots op","💡 Tempo na ruim 2 uur: 7:00–9:00 min/km is normaal, ook voor getrainde lopers. Laat je tempo-ego los","💡 Cardiale drift kan bij deze duur 10–12 bpm toevoegen — ga op tijd langzamer lopen, wacht niet tot je wel moet","💡 Herstel: minimaal 48 uur rustige activiteit. Slaap is het belangrijkste middel voor trainingsaanpassing"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-20' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '150-minute Zone 2 run. This is a significant athletic undertaking — treat it as a training event, not just a run.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop 180 minuten in zone 2 — 3 uur. Dit is een duurloopvolume op eliteniveau. Bereid je voor als op een wedstrijd: slaap, voeding, drinken, uitrusting","Hartslag 120–130 bpm. Verwacht tempo: 7:00–9:00 min/km. Na 90 minuten loop je waarschijnlijk langzamer — dat klopt en hoort bij deze duur","Voeding: vanaf de start elke 40 minuten 30–40 g koolhydraten. Drink elke 20 minuten. Overweeg elektrolyten (natrium) bij lopen van meer dan 2 uur","Deze loop gaat niet om tempo, snelheid of afstand. Het gaat om 3 uur aaneengesloten aeroob werk in zone 2. De aanpassing die deze ene sessie oplevert is uitzonderlijk"]'), '$.cues_nl', json('["💡 Duurlopen van 3 uur in zone 2 zijn de basis van marathon- en ultratraining. Je leert je lichaam om op vet te lopen","💡 Na ruim 2 uur is je vetverbranding bijna maximaal. Je lichaam leert glycogeen te sparen — het duurt weken voordat je dat merkt","💡 Je hartslag gaat oplopen. Na 2,5 uur is 128–133 bpm bij wandelen en dribbelen nog steeds zone 2-werk. Ga niet harder","💡 Herstel: morgen een volledige rustdag, eiwitrijk eten en als het kan 9 uur slaap of meer"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-21' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = '180-minute Zone 2 run — 3 hours. This is elite-range long run volume. Prepare as you would for a race: sleep, nutrition, hydration, gear.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Kies je tempo zo dat je hartslag uitkomt op 130 bpm — dit is zone 2, de zone voor je aerobe basis","Richttempo: 6:30–8:30 min/km (7–9 km/u). Begin op de loopband met 7,5 km/u en 1% helling en pas aan. Langzamer is beter dan sneller — je hartslag bepaalt, niet je tempo","Stijgt je hartslag boven 135 bpm, loop dan 5–10 sec/km langzamer en blijf daar. Dat is geen falen — het is precies goede zone 2-training","Laatste 5 minuten: merk op hoe stabiel je ademhaling voelt. Dit is je aerobe motor op zijn optimale intensiteit"]'), '$.cues_nl', json('["💡 Praattest: zeg hardop een hele zin. Lukt dat niet, loop dan langzamer — je bent uit zone 2","💡 Zone 2 vergroot je mitochondriale dichtheid en maakt je vetverbranding efficiënter. De meeste lopers gaan te hard op rustige dagen","💡 Hartslag 130 = ongeveer 65–70% van je maximale hartslag. Pas je doel aan met ±5 bpm op basis van je leeftijd en conditie","💡 Gepolariseerde regel: deze sessie hoort bijna te makkelijk te voelen. Bewaar de zware inspanning voor je HIIT-dagen"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-7' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Set your pace so your heart rate settles at 130 bpm — this is Zone 2, your aerobic base zone.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Begin in een tempo waarbij je hartslag uitkomt op 130 bpm. Voor de meeste lopers is dat 7–9 km/u (6:40–8:30 min/km)","Houd deze inspanning de volle 25 minuten vast. Negeer je tempo — loopt je hartslag op een heuvel op tot boven 135, maak dan je pas korter en wandel het laatste stuk stevig door","Je hoort de hele loop een gesprek te kunnen voeren. Kun je geen 3–4 woorden zeggen zonder naar adem te happen, dan loop je te hard","Na de sessie: je rustige tempo wordt in de loop van weken sneller naarmate je aerobe basis groeit"]'), '$.cues_nl', json('["💡 Doelhartslag zone 2: de hele loop 125–135 bpm","💡 Loopband: 7,5–9 km/u met 1% helling. Buiten: laat je hartslag bepalen, negeer je tempo","💡 Op deze intensiteit draait je aerobe motor op vet — hier bouw je je basis","💡 Je langzaam voelen klopt. De meeste lopers zitten te vaak in de inefficiënte middenzone"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-8' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Start at a pace where your heart rate settles at 130 bpm. For most runners this is 7–9 km/h (6:40–8:30 min/km).';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Kom binnen de eerste 5 minuten in zone 2 — hartslag 125–135 bpm, een tempo waarbij je makkelijk kunt praten","Houd dit gelijkmatige tempo de volle 30 minuten vast. Pas je tempo aan het terrein aan: heuvelop = rustigere pas, heuvelaf = laat het vanzelf lopen","Richttempo: 6:30–8:30 min/km (7–9 km/u) op vlak terrein. Op de loopband is 8 km/u met 1% helling een goed richtpunt","Mentale check na 20 minuten: is je ademhaling duidelijk veranderd sinds minuut 5, dan schuif je op naar zone 3 — loop langzamer"]'), '$.cues_nl', json('["💡 Hartslag zone 2: 125–135 bpm. Duwt een heuvel je naar 140 of hoger, wandel dan het laatste stuk","💡 30 minuten zone 2 is een volledige aerobe prikkel — harder hoeft niet","💡 Je zone 2-tempo wordt duidelijk sneller na 8–12 weken regelmatig rustig hardlopen","💡 Rustige dagen rustig, zware dagen zwaar. Dat is de basis van gepolariseerd trainen"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-continuous-level-9' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Settle into Zone 2 within the first 5 minutes — HR 125–135 bpm, pace that allows easy conversation.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop rustig op een makkelijke, beheerste inspanning — zie het als doelgericht dribbelen, niet als een sprint","Wandel stevig door zodra de rusttimer start. Blijf bewegen en adem rustig door","Herhaal dit alle rondes. Moet je eerder stoppen, dan geeft je lichaam je het juiste signaal"]'), '$.cues_nl', json('["💡 Doelinspanning: 70–80% van je maximum — je hartslag hoort tijdens elk loopblok 140–155 bpm te halen","💡 Richttempo: 6:00–8:30 min/km (7–10 km/u). Op de loopband is 7,5 km/u een goed begin","💡 Wandelherstel is niet vrijblijvend — volledig herstel tussen de inspanningen is wat HIIT laat werken","💡 Dit is gepolariseerd trainen: het lopen is zwaar, het wandelen echt rustig"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-interval-level-1' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Run gently at an easy, controlled effort — think of it as a purposeful shuffle, not a sprint.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop op een stevige, beheerste inspanning — geen sprint, maar je werkt duidelijk hard","Wandel rustig door zodra de rusttimer start. Sta niet stil — houd je benen in beweging","Maak alle rondes af. Je loopt en wandelt even lang"]'), '$.cues_nl', json('["💡 Doelinspanning: 80–85% van je maximum — je hartslag hoort tijdens elk interval 155–165 bpm te halen","💡 Richttempo: 5:30–7:30 min/km (8–11 km/u). Loopband: 9–10 km/u bij inspanning, 5 km/u wandelen","💡 Landen op je middenvoet belast je gewrichten minder — land niet eerst op je hiel","💡 Kun je door je ademhaling helemaal niet meer praten, ga dan 0,5 km/u langzamer"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-interval-level-2' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Run at a strong, controlled effort — not a sprint, but clearly working hard.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop op een zware inspanning die je volhoudt — je ademhaling hoort duidelijk zwaar te zijn","Wandel zodra de rusttimer begint. Adem diep en laat je hartslag zakken tot onder 130 bpm","Maak alle rondes af. Regelmaat gaat boven snelheid — elke ronde op dezelfde inspanning"]'), '$.cues_nl', json('["💡 Doelinspanning: 82–87% van je maximum — doelhartslag 158–168 bpm tijdens de inspanning","💡 Richttempo: 5:00–7:00 min/km (8,5–12 km/u). Loopband: 10 km/u bij inspanning, 5,5 km/u wandelen","💡 Ontspan je schouders en handen — spanning kost energie","💡 Wandelherstel: je hartslag hoort onder 130 te zakken voordat de volgende inspanning begint"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-interval-level-3' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Run at a hard, sustained effort — your breathing should be clearly laboured.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop in een stevig tempo dat je volhoudt — zo zwaar dat praten moeite kost","Wandel zodra de rusttimer start. Breng je hartslag actief omlaag — adem diep","Maak alle rondes af. Je bouwt nu echt aeroob vermogen op"]'), '$.cues_nl', json('["💡 Doelinspanning: 85–88% van je maximum — doelhartslag 162–170 bpm tijdens de inspanning","💡 Richttempo: 5:00–6:30 min/km (9–12 km/u). Loopband: 10–11 km/u bij inspanning, 5,5 km/u wandelen","💡 Korte passen met een hoge pasfrequentie werken bij HIIT efficiënter dan lange, trage passen","💡 Heupen naar voren, lichaam rechtop — niet ingezakt. Je houding houdt je tempo vast"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-interval-level-4' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Run at a strong, sustainable pace — hard enough that speech requires effort.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop in een tempo dat je ademhaling uitdaagt — praten kost echt moeite, maar één woord lukt nog","Wandel zodra de rusttimer start. Je hartslag hoort merkbaar te zakken — mik op onder 130","Maak alle rondes af. Je bouwt serieuze HIIT-conditie op"]'), '$.cues_nl', json('["💡 Doelinspanning: 87–90% van je maximum — doelhartslag 165–175 bpm tijdens de inspanning","💡 Richttempo: 4:45–6:00 min/km (10–12,5 km/u). Loopband: 11 km/u bij inspanning, 6 km/u wandelen","💡 Zwaai je armen krachtig naar voren — je armen bepalen het ritme van je benen","💡 Ervaren inspanning: 8–9 op 10. Voelt het niet zwaar, voer dan het tempo op"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-interval-level-5' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Run at a pace that challenges your breathing — speaking takes real effort but one word is possible.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Loop in een stevig, beheerst tempo. Je komt in de buurt van je lactaatdrempel — dit hoort echt zwaar te voelen","Wandel zodra de rusttimer start — gebruik het actief om je voor te bereiden op de volgende inspanning","Maak alle rondes af. Op dit niveau is wandelen strategisch herstel, geen pauze"]'), '$.cues_nl', json('["💡 Doelinspanning: 88–92% van je maximum — doelhartslag 168–178 bpm tijdens de inspanning","💡 Richttempo: 4:30–5:30 min/km (11–13 km/u). Loopband: 11,5–12,5 km/u bij inspanning, 6 km/u wandelen","💡 Inspanningen van 5 minuten op deze intensiteit verhogen je lactaatdrempel — hier bouw je echte conditie op","💡 Houd je techniek scherp, ook als je moe bent — bij vermoeidheid is de kans op blessures het grootst"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-interval-level-6' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Run at a strong, controlled pace. You are approaching lactate threshold — this should feel genuinely demanding.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Warm up with a 5-minute easy jog","Run fast for 60 seconds — a hard effort, controlled but challenging","Recover for 90 seconds with a walk or a very easy jog","Repeat the hard effort and the recovery for the rounds of your session","Cool down with a 3-minute easy walk"]'), '$.cues', json('["Hard effort = you could not have a conversation","Recovery must be genuinely easy — it prepares the next rep","Focus on keeping form during hard effort: tall, relaxed, quick feet","💡 Beginner: 5 rounds · hard pace 5:30–6:30 min/km","💡 Intermediate: 8 rounds · hard pace 4:30–5:00 min/km","💡 Advanced: 10–12 rounds · hard pace 3:45–4:15 min/km"]'), '$.steps_nl', json('["Doe een warming-up van 5 minuten rustig joggen","Loop 60 seconden hard — een zware inspanning, beheerst maar uitdagend","Herstel 90 seconden met wandelen of heel rustig joggen","Herhaal de inspanning en het herstel voor de rondes van je sessie","Sluit af met een cooling-down van 3 minuten rustig wandelen"]'), '$.cues_nl', json('["Zware inspanning = je zou geen gesprek kunnen voeren","Het herstel moet echt rustig zijn — het bereidt je voor op de volgende herhaling","Let tijdens de zware inspanning op je techniek: lang, ontspannen, snelle voeten","💡 Beginner: 5 rondes · snel tempo 5:30–6:30 min/km","💡 Gemiddeld: 8 rondes · snel tempo 4:30–5:00 min/km","💡 Gevorderd: 10–12 rondes · snel tempo 3:45–4:15 min/km"]')), updated_at_ms = 1795305600000 WHERE slug = 'run-intervals-outdoor' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 6 AND json_extract(instructions_json, '$.steps[0]') = 'Warm-up: 5-minute easy jog';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit on the edge of a sturdy chair, feet flat","Alternate throwing punches forward — jab, cross, hook","Add speed and rhythm","Keep punching without stopping for 30–60 seconds"]'), '$.cues', json('["Rotate torso with each punch","Elbows stay in on jab/cross","Great seated cardio option late pregnancy or early postnatal"]'), '$.steps_nl', json('["Ga op de rand van een stevige stoel zitten, voeten plat","Stoot afwisselend naar voren — jab, cross, hoek","Voer tempo en ritme op","Blijf 30–60 seconden onafgebroken stoten"]'), '$.cues_nl', json('["Draai je bovenlichaam mee bij elke stoot","Ellebogen blijven dicht bij je lichaam bij jab en cross","Prima cardio-optie zittend, laat in de zwangerschap of vlak na de bevalling"]')), updated_at_ms = 1795305600000 WHERE slug = 'seated-cardio-punch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit on the edge of a sturdy chair, feet flat';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand with your feet shoulder-width apart and your knees slightly bent","Throw jab-cross combinations","Add hooks and uppercuts","Move feet between combinations"]'), '$.cues', json('["Stays in one spot","Good stress relief"]'), '$.steps_nl', json('["Sta met je voeten op schouderbreedte en je knieën licht gebogen","Sla combinaties van jab en cross","Voeg hoeken en uppercuts toe","Beweeg je voeten tussen de combinaties door"]'), '$.cues_nl', json('["Je blijft op één plek","Goed om stress kwijt te raken"]')), updated_at_ms = 1795305600000 WHERE slug = 'shadow-boxing' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stance: feet shoulder-width, slight bend in knees';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta met je voeten op heupbreedte","Maak een zijpas naar rechts (stap-sluit-stap) en tik met je rechtervoet","Maak een zijpas naar links (stap-sluit-stap) en tik met je linkervoet","Houd een vast ritme aan, 30–60 seconden"]'), '$.cues_nl', json('["Blijf licht op je voeten","Laat je armen vanzelf meezwaaien","Zijwaartse cardio met weinig impact"]')), updated_at_ms = 1795305600000 WHERE slug = 'shuffle-tap' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with feet hip-width';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Drive knees up quickly, pumping arms","Lean slightly forward from ankles","Give maximum effort for 20–30 seconds","Rest and repeat"]'), '$.cues', json('["Push the pace — this should feel hard","High impact — not for pregnancy","Great HIIT finisher"]'), '$.steps_nl', json('["Breng je knieën snel omhoog en pomp met je armen","Leun licht naar voren vanuit je enkels","Geef 20–30 seconden alles","Rust en herhaal"]'), '$.cues_nl', json('["Ga voluit — dit moet zwaar voelen","Hoge impact — niet tijdens de zwangerschap","Ideale HIIT-afsluiter"]')), updated_at_ms = 1795305600000 WHERE slug = 'sprint-in-place' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Drive knees up quickly, pumping arms';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zak in een squat (bovenbenen horizontaal of iets hoger)","Pulseer in kleine bewegingen op en neer — ongeveer 5 cm","Houd de spanning op je bovenbenen","Pulseer 20–30 seconden"]'), '$.cues_nl', json('["Kom niet helemaal omhoog — blijf in dat kleine bereik","Dit brandt snel!","Heel goed voor het uithoudingsvermogen van je bilspieren en bovenbenen"]')), updated_at_ms = 1795305600000 WHERE slug = 'squat-pulse' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Lower into a squat position (parallel or above parallel)';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Doe een warming-up van 5 minuten op 70–90 W en 80 rpm — je hartslag hoort voor de intervallen 110–120 te halen","Inspanningsinterval: verhoog de weerstand tot je doelvermogen. Beginners: 130–170 W. Gemiddeld: 170–230 W. Gevorderd: 230–300 W of meer. Trapfrequentie 90–110 rpm. Dit hoort te voelen als een 8–9 op 10 — hartslag 165–178 bpm","Herstelinterval: zak terug naar 60–90 W op 70–80 rpm. Laat je hartslag zakken tot 120–130 bpm voor de volgende inspanning. Blijf trappen","Herhaal inspanning en herstel. Doe een cooling-down van 5 minuten op 60–80 W en 75 rpm"]'), '$.cues_nl', json('["💡 Opbouw in watt: beginners 130–170 W inspanning / 60–80 W herstel. Gemiddeld 170–230 W / 70–90 W. Gevorderd 230–300 W of meer / 80–100 W","💡 Trapfrequentie tijdens de inspanning: 90–110 rpm. Een hoge trapfrequentie traint je hart en longen, een hoge weerstand traint je benen. Doe allebei","💡 HIIT op de hometrainer is een van de veiligste vormen van intensieve cardio — geen impact, gelijkmatige weerstand","💡 Doelhartslag tijdens de inspanning: 165–178 bpm. Haal je 160 bpm niet, zet de weerstand dan 2–3 standen hoger"]')), updated_at_ms = 1795305600000 WHERE slug = 'static-bike-hiit' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Warm up at 70–90W, 80 RPM for 5 minutes — HR should reach 110–120 before intervals.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Stel de weerstand zo in dat je soepel trapt op 80–90 rpm zonder te stuiteren op het zadel. Begin voorzichtig — verhoog de weerstand als je hartslag na 5 minuten onder 120 blijft","Doelvermogen: 80–100 W voor beginners, 100–150 W voor gemiddelde en 150–180 W voor getrainde fietsers. Laat je hartslag leidend zijn: kom uit op 125–135 bpm","Houd dit gelijkmatige tempo de hele sessie vast. Je trapfrequentie blijft tussen 80 en 90 rpm — soepele, beheerste trapcirkels, geen hakkende halen","Check je hartslag na 10, 20 en 30 minuten. Die hoort binnen 5 bpm van je zone 2-doel te blijven. Pas de weerstand zo nodig 1–2 standen aan"]'), '$.cues_nl', json('["💡 80–90 rpm is de trapfrequentie voor zone 2 — soepel trappen op gemiddelde weerstand traint je aerobe efficiëntie","💡 Doelen in watt: beginners 80–100 W, gemiddeld 100–140 W, gevorderd 140–180 W. Bij de meeste mensen hoort daar een hartslag van 125–135 bij","💡 Praattest: je hoort de hele tijd in hele zinnen te kunnen praten. Het fietsen hoort licht te voelen","💡 Fietsen in zone 2 heeft weinig impact maar geeft veel prikkel. 45 minuten levert een aerobe aanpassing op die gelijkstaat aan 35 minuten hardlopen in zone 2"]')), updated_at_ms = 1795305600000 WHERE slug = 'static-bike-zone2' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Set resistance so you spin smoothly at 80–90 RPM without bouncing in the saddle. Start conservative — adjust resistance up if HR stays below 120 after 5 minutes.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Stel de zadelhoogte zo in dat je knie bijna gestrekt is onderaan de trapbeweging","Begin op lage weerstand en trap 3–4 minuten los als warming-up","Verhoog de weerstand tot je doelniveau en zoek een vast ritme","Houd een trapfrequentie van 70–90 rpm aan","Check elke 5 minuten je inspanning — zet de weerstand iets hoger als het te makkelijk voelt","Laatste 3 minuten: verlaag de weerstand en fiets uit"]'), '$.cues_nl', json('["Zit rechtop — hang niet over het stuur","Span je core de hele tijd licht aan","Let op een soepele, gelijkmatige druk met beide benen","💡 Beginner: lichte tot gemiddelde weerstand · RPE 4–5 · ~30 min","💡 Gemiddeld: gemiddelde weerstand · RPE 6 · ~40 min","💡 Gevorderd: gemiddelde tot zware weerstand · RPE 7 · ~50 min"]'), '$.pregnancy_note_nl', 'Blijf op een inspanning waarbij je kunt praten (RPE ≤ 5). Een rechtop zittende fiets is laat in de zwangerschap meestal comfortabeler dan een ligfiets.'), updated_at_ms = 1795305600000 WHERE slug = 'stationary-bike-steady' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 6 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 6 AND json_extract(instructions_json, '$.steps[0]') = 'Adjust seat height so your knee is almost straight at the bottom of the pedal stroke';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Stel je fiets af — zadelhoogte zo dat je knie licht gebogen is onderaan de trapbeweging","Begin met 5 minuten rustig trappen op 80–90 rpm als warming-up","Ga naar je doelvermogen of je doelinspanning en houd dat gelijkmatig vast","Check elke 5 minuten — pas de weerstand aan als je afwijkt","Houd je trapfrequentie de hele tijd boven 80 rpm","Laatste 3–5 minuten: verlaag de weerstand en trap rustig uit als cooling-down"]'), '$.cues_nl', json('["Trap soepele cirkels — duw bovenaan naar voren, trek onderaan naar achteren","Ontspan je handen en schouders — je benen doen het werk","Adem ritmisch — stem je ademhaling af op je trapbeweging","💡 Beginner: 70–100 W · 80–90 rpm · RPE 4–5","💡 Gemiddeld: 120–155 W · 85–95 rpm · RPE 6","💡 Gevorderd: 170–230 W · 90–100 rpm · RPE 7"]'), '$.pregnancy_note_nl', 'Blijf op een inspanning waarbij je kunt praten (RPE ≤ 5). Stop als je duizelig of kortademig wordt of druk in je bekken voelt.'), updated_at_ms = 1795305600000 WHERE slug = 'steady-indoor-cycle' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 6 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 6 AND json_extract(instructions_json, '$.steps[0]') = 'Set your bike up — saddle height so your knee has a slight bend at the bottom of the pedal stroke';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand tall with your feet together","Step your right foot to the right","Bring your left foot in to meet it","Step your left foot to the left and bring your right foot in to meet it","Swing your arms along to raise the intensity"]'), '$.cues', json('["Quiet movement — works well on days when you are not in workout clothes","Keep a comfortable pace"]'), '$.steps_nl', json('["Sta rechtop met je voeten bij elkaar","Stap met je rechtervoet naar rechts","Breng je linkervoet erbij","Stap met je linkervoet naar links en breng je rechtervoet erbij","Zwaai je armen mee voor meer intensiteit"]'), '$.cues_nl', json('["Stille beweging — handig op dagen dat je geen sportkleding aan hebt","Houd een comfortabel tempo aan"]')), updated_at_ms = 1795305600000 WHERE slug = 'step-touch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Step right foot to the right';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Begin na 10 minuten rustig joggen met de versnellingen: versnel geleidelijk over 80–100 m tot ongeveer 90% van je topsnelheid","Houd die 90% vast in het middelste derde deel en rem dan geleidelijk af over de laatste 30 m","Wandel of jog rustig terug naar de start. Herstel volledig tussen de versnellingen"]'), '$.cues_nl', json('["💡 Versnellingen leren je zenuwen en spieren hoe snel lopen voelt — ze verbeteren je loopefficiëntie","Let op ontspanning op snelheid: losse handen, zachte schouders, lange houding"]')), updated_at_ms = 1795305600000 WHERE slug = 'stride-outs' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'After a 10-minute easy jog, begin striding: gradually accelerate over 80–100 m to about 90% of your top speed.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Walk or jog easily for 5 minutes to warm up","Build to tempo pace — comfortably hard, not all-out","Maintain this pace for the bulk of the run","Check with the two-word test: you can say two words but not a full sentence","Keep your form: tall posture, slight forward lean, quick light steps","Finish with a 5-minute easy jog or walk to cool down"]'), '$.cues', json('["Tempo = about 80% of max heart rate","If you can chat comfortably, go faster. If gasping, back off.","Think: controlled discomfort — not survival mode","💡 Beginner: 6:00–7:00 min/km · ~25 min (including warm-up/cool-down)","💡 Intermediate: 5:00–5:45 min/km · ~30 min total","💡 Advanced: 4:00–4:45 min/km · ~35 min total"]'), '$.steps_nl', json('["Wandel of jog 5 minuten rustig als warming-up","Versnel naar je tempolooptempo — comfortabel zwaar, niet voluit","Houd dit tempo het grootste deel van de loop vast","Check met de tweewoordentest: je kunt twee woorden zeggen, maar geen hele zin","Let op je techniek: rechte houding, licht naar voren geleund, snelle lichte passen","Sluit af met 5 minuten rustig joggen of wandelen als cooling-down"]'), '$.cues_nl', json('["Tempo = ongeveer 80% van je maximale hartslag","Kun je makkelijk kletsen, ga dan sneller. Hap je naar adem, doe dan een stap terug","Denk aan: beheerst ongemak — geen overlevingsstand","💡 Beginner: 6:00–7:00 min/km · ~25 min (inclusief warming-up en cooling-down)","💡 Gemiddeld: 5:00–5:45 min/km · ~30 min in totaal","💡 Gevorderd: 4:00–4:45 min/km · ~35 min in totaal"]')), updated_at_ms = 1795305600000 WHERE slug = 'tempo-run-outdoor' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 6 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 6 AND json_extract(instructions_json, '$.steps[0]') = 'Walk or easy jog 5 minutes to warm up';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op pad over oneffen terrein in een tempo waarbij je een gesprek kunt voeren","Maak je passen korter op de klimmen","Daal rustig af — daar verzwik je je enkels"]'), '$.cues_nl', json('["Kijk tijdens het lopen waar je je voeten zet, niet naar het uitzicht","Stokken helpen bij langere afdalingen","💡 Zone 2-werk dat niet als training voelt"]')), updated_at_ms = 1795305600000 WHERE slug = 'trail-hike-steady' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Head out on uneven ground at a pace you could hold a conversation at.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zoek een heuvel waar je op inspanning 60–90 seconden over doet om boven te komen","Werk hard tot aan de top","Wandel naar beneden en herstel volledig","Herhaal dit voor het opgegeven aantal rondes"]'), '$.cues_nl', json('["Korte passen en snelle voeten op de klim","Wandel de afdaling — niet rennen","💡 Bouwt loopkracht op met veel minder impact dan snelheidswerk op vlak terrein"]')), updated_at_ms = 1795305600000 WHERE slug = 'trail-hill-repeats' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Find a hill that takes 60–90 seconds to climb at effort.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Kies een trail die past bij je conditie — brede, goed onderhouden paden voor beginners","Loop op een rustige inspanning waarbij je kunt praten. Ga heuvelop over op wandelen en pak het lopen weer op zodra het vlak is","Let op waar je voeten landen — oneffen terrein vraagt je volle aandacht"]'), '$.cues_nl', json('["💡 Trailrunning versterkt de stabiliserende spieren rond je enkels, knieën en heupen sneller dan lopen op de weg","Inspanning gaat boven tempo — heuvels maken je langzamer en dat mag. De inspanning telt"]')), updated_at_ms = 1795305600000 WHERE slug = 'trail-run-easy' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Choose a trail suitable for your fitness level — wide, well-maintained paths for beginners.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zet de helling op 1%. Doe een warming-up van 3 minuten op 6 km/u — je hartslag hoort 110–120 bpm te halen voordat de intervallen beginnen","Inspanningsinterval: verhoog naar 11–14 km/u. Doelinspanning: 85–90% van je maximum, hartslag 160–175 bpm. Beginners starten op 10–11 km/u en bouwen dat per sessie op","Herstelinterval: ga terug naar 5,5–6,5 km/u (stevig wandelen). Laat je hartslag onder 130 bpm zakken voor de volgende inspanning. Volledig herstel is wat HIIT laat werken","Herhaal het patroon van inspanning en herstel. Laatste 3 minuten: cooling-down op 5,5 km/u. Stop nooit abrupt na zware intervallen"]'), '$.cues_nl', json('["💡 Doelsnelheden: inspanning 11–14 km/u (gelijk aan 4:17–5:27 min/km). Herstel 5,5–6 km/u wandeltempo","💡 Hartslag tijdens de inspanning: 160–175 bpm. Haal je 158 bpm niet, ga dan 0,5 km/u sneller","💡 Programmeer je inspannings- en herstelsnelheid voordat je begint — wisselen moet snel gaan (binnen 10 seconden)","💡 HIIT op de loopband: een herstelverhouding van 2:1 (bijv. 1 min inspanning / 2 min wandelen) is gangbaar voor beginners"]')), updated_at_ms = 1795305600000 WHERE slug = 'treadmill-hiit' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Set incline to 1%. Warm up at 6 km/h for 3 minutes — HR should reach 110–120 bpm before intervals begin.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zet de loopband op 6–10% helling en een gemiddelde snelheid. Doe een warming-up van 2 minuten, vlak en rustig","Loop de hele duur op deze helling en let op je klimtechniek: knieën krachtig omhoog en je armen actief meezwaaien","Ga elke 5 minuten 1 minuut terug naar vlak om te herstellen"]'), '$.cues_nl', json('["💡 Houd de leuningen niet vast — daarmee verdwijnt het grootste deel van het effect op je hart en longen","Lopen op een helling bouwt snel je bilspieren en kuiten op; loop langzamer dan op vlak terrein"]')), updated_at_ms = 1795305600000 WHERE slug = 'treadmill-hill-run' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Set the treadmill to 6–10% incline at a moderate speed. Warm up 2 minutes at flat and easy.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Doe een warming-up van 3–4 minuten rustig wandelen of joggen. Zet de snelheid op een uitdagend tempo dat je kunt volhouden","Loop 30–60 seconden op deze hogere snelheid en ga dan 90–120 seconden terug naar een hersteltempo","Herhaal deze afwisseling van inspanning en rust de hele sessie. Sluit af met een cooling-down van 2 minuten wandelen"]'), '$.cues_nl', json('["💡 Stel het tempo in voordat je opstapt — gepruts met de knoppen tijdens een interval leidt af","Gebruik de hele tijd 1% helling; dat lijkt meer op de inspanning van buiten lopen"]')), updated_at_ms = 1795305600000 WHERE slug = 'treadmill-intervals' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Warm up 3–4 minutes at an easy walk/jog. Set the speed to a challenging but sustainable pace.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zet de helling op 1% — dat lijkt meer op buiten lopen (het compenseert het ontbreken van windweerstand)","Begin met 2 minuten rustig wandelen en verhoog daarna geleidelijk de snelheid","Zoek je doelsnelheid en houd die vast","Kijk naar voren en iets omlaag — niet naar je voeten","Houd de leuningen niet vast, tenzij het voor je veiligheid nodig is","Laatste 2–3 minuten: verlaag de snelheid en wandel uit als cooling-down"]'), '$.cues_nl', json('["1% helling is voor de meeste lopers precies goed","Maak je passen niet te groot — je voeten horen onder je heupen te landen","Korte, snelle passen zijn efficiënter dan grote sprongen","💡 Beginner: 7,5–8,5 km/u · 1% helling · ~20 min","💡 Gemiddeld: 9,5–11,0 km/u · 1% helling · ~25 min","💡 Gevorderd: 12,0–14,5 km/u · 1–2% helling · ~30 min"]')), updated_at_ms = 1795305600000 WHERE slug = 'treadmill-run-steady' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 6 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 6 AND json_extract(instructions_json, '$.steps[0]') = 'Set incline to 1% — this better replicates outdoor running (compensates for no wind resistance)';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zet de loopband op 1% helling — dat compenseert het ontbreken van luchtweerstand en komt dichter bij de inspanning van buiten lopen","Begin op 7,5 km/u en laat je hartslag in 3–5 minuten stabiliseren. Doelzone: 125–135 bpm. Pas de snelheid aan in stappen van 0,3 km/u tot je je eigen zone 2-snelheid hebt gevonden","Houd je zone 2-snelheid de hele sessie vast. Richtsnelheden: beginners 7–8 km/u, gemiddeld 8–9,5 km/u, getraind 9,5–11 km/u. Je hartslag bepaalt — niet je tempo","Komt je hartslag op enig moment boven 135 (vooral bij lange sessies), ga dan 0,3 km/u langzamer en blijf daar. Cardiale drift na ruim 30 minuten is normaal"]'), '$.cues_nl', json('["💡 Praattest: zeg 5 woorden op je gemak, zonder naar adem te happen. Lukt dat niet, dan zit je boven zone 2 — ga langzamer","💡 Zone 2-referentie op de loopband: 8 km/u met 1% helling past bij de meeste recreatieve lopers (hartslag ~125–135)","💡 Loop voor zone 2 nooit vlak op een loopband — 1% helling is nodig om nauwkeurig te trainen","💡 Je zone 2-tempo wordt 15–25 sec/km sneller na 8 weken regelmatig trainen, zonder dat het zwaarder voelt"]')), updated_at_ms = 1795305600000 WHERE slug = 'treadmill-zone2' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Set treadmill to 1% incline — this compensates for the absence of air resistance and more closely matches outdoor running effort.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand with feet hip-width","Jump and drive both knees toward chest at the peak","Land softly with knees bent","Go straight into the next rep"]'), '$.cues', json('["Maximum effort jump","Very high impact — not for pregnancy or early postnatal","Great for athletic conditioning"]'), '$.steps_nl', json('["Sta met je voeten op heupbreedte","Spring en trek op het hoogste punt beide knieën naar je borst","Land zacht met gebogen knieën","Ga direct door naar de volgende herhaling"]'), '$.cues_nl', json('["Spring met maximale inzet","Zeer hoge impact — niet tijdens de zwangerschap of vlak na de bevalling","Ideaal voor atletische conditie"]')), updated_at_ms = 1795305600000 WHERE slug = 'tuck-jump' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with feet hip-width';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Laad je rugzak of vest tot het voorgeschreven gewicht; stel de banden zo af dat de rugzak hoog en strak zit","Bepaal je tempo: 5,5 km/u (militaire norm) of 6 km/u (gevorderd)","Marcheer met een rechte houding — borst omhoog, schouders naar achteren, core de hele tijd aangespannen","Laat je armen vanzelf meezwaaien; korte, snelle passen zijn efficiënter dan lange passen","Houd je tempo bij met een gps-horloge of app; blijf binnen ±0,3 km/u van je doelsnelheid"]'), '$.cues_nl', json('["Het gewicht telt op — wat in minuut 5 licht voelt, voelt in minuut 20 zwaar","Rol je voet af van hiel naar teen op marstempo — niet sloffen","💡 Beginner (0 kg): let op tempo en houding. Opbouw: elke 2 weken +5–10 kg","💡 Gemiddeld (25 kg): standaardgewicht voor de voorbereiding op Defensie","💡 Gevorderd (35–45 kg): komt overeen met de doelen van Cluster 4–6 Opleiding"]')), updated_at_ms = 1795305600000 WHERE slug = 'weighted-march' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 5 AND json_extract(instructions_json, '$.steps[0]') = 'Load your rucksack or vest to the prescribed weight; adjust straps so the pack sits high and snug';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand tall with your feet together","Step right foot wide to the right","Bring left foot to meet it, touching down briefly","Step left wide to the left","Bring your right foot in to meet it","Add arm raises for intensity"]'), '$.cues', json('["Wider steps = more glute engagement","Keep chest up","Great continuous warm-up movement"]'), '$.steps_nl', json('["Sta rechtop met je voeten bij elkaar","Stap met je rechtervoet breed naar rechts","Breng je linkervoet erbij en tik kort de vloer aan","Stap met links breed naar links","Breng je rechtervoet erbij","Breng je armen omhoog voor meer intensiteit"]'), '$.cues_nl', json('["Bredere passen = meer werk voor je bilspieren","Houd je borst omhoog","Ideale doorlopende warming-up"]')), updated_at_ms = 1795305600000 WHERE slug = 'wide-step-touch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 6 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Vertrek in een tempo waarbij je volledig kunt praten — je moet de hele loop in hele zinnen kunnen spreken","Houd je inspanning gelijk, niet je tempo; raak je buiten adem, loop dan langzamer","Sluit af met 2 minuten wandelen als cooling-down"]'), '$.cues_nl', json('["💡 Ademen door je neus is een handige graadmeter — moet je je mond opendoen, dan zit je mogelijk boven zone 2","Zone 2 bouwt je aerobe basis en je vetverbranding op. Saai is precies de bedoeling"]')), updated_at_ms = 1795305600000 WHERE slug = 'zone2-easy-run' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Set off at a fully conversational pace — you must be able to speak in full sentences throughout.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Begin in een hoge plank — handen onder je schouders, lichaam recht","Trek je rechterknie naar je borst en wissel dan snel — rechterbeen terug, linkerknie naar voren","Wissel je benen af in een loopbeweging en houd je heupen recht","Houd de hele tijd een vast ritme aan"]'), '$.cues_nl', json('["Je heupen blijven vlak — laat ze niet bij elke knie omhoog veren","Hoe hoger het tempo, hoe meer het van je hart en longen vraagt","💡 Langzaam = focus op kracht in je core. Snel = conditie. Begin langzaam om de techniek goed te krijgen"]')), updated_at_ms = 1795305600000 WHERE slug = 'mountain-climber' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Start in a high plank position — hands under shoulders, body straight';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit with one leg in front bent about 90 degrees and the other leg out to the side bent about 90 degrees","Sit tall and lean gently over your front shin to open the hip (external rotation)","Come back up and rotate your chest toward your back leg (internal rotation)","Move slowly, keep breathing, then switch legs"]'), '$.cues', json('["Keep your back long — fold from the hips, do not round","Go to a firm stretch, never to pain in your knee or hip"]'), '$.steps_nl', json('["Ga zitten met één been voor je, ongeveer 90 graden gebogen, en het andere been opzij, ook ongeveer 90 graden gebogen","Zit rechtop en leun rustig over je voorste scheenbeen om je heup te openen (exorotatie)","Kom terug omhoog en draai je borst naar je achterste been (endorotatie)","Beweeg langzaam, adem door en wissel daarna van been"]'), '$.cues_nl', json('["Houd je rug lang — buig vanuit je heupen, maak je rug niet bol","Ga tot een stevige rek, nooit tot pijn in je knie of heup"]')), updated_at_ms = 1795305600000 WHERE slug = '90-90-stretch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 0 AND json_extract(instructions_json, '$.steps[0]') = 'Sit with one leg in front bent ~90 degrees and the other to the side bent ~90 degrees.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Lig op je zij in foetushouding, knieën op elkaar en 90° gebogen, armen gestrekt voor je","Houd je knieën bij elkaar en je onderlichaam stil. Draai je bovenste arm open richting het plafond en verder naar achteren","Volg je hand met je ogen. Kom terug en herhaal. Wissel na je herhalingen van kant"]'), '$.cues_nl', json('["💡 Adem uit terwijl je opendraait — de uitademing ontspant je borst en geeft meer ruimte om te draaien","Je onderlichaam blijft helemaal stil — alle beweging komt uit je bovenrug"]')), updated_at_ms = 1795305600000 WHERE slug = 'active-thoracic-rotation' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on your side in a foetal position, knees stacked and bent to 90°, arms extended in front.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga met je gezicht naar een muur staan, armen gestrekt, handen plat tegen de muur op borsthoogte. Zet één voet ongeveer 60–90 cm naar achteren, met je tenen recht naar voren en je hiel plat op de vloer","Leun rustig naar de muur door je voorste knie te buigen. Houd je achterste knie gestrekt en je achterste hiel op de grond. Voel de rek in de kuit van je achterste been (rek van de gastrocnemius)","Buig na 20–30 seconden je achterste knie een beetje — je hiel blijft op de vloer. Zo verschuift de rek dieper naar je onderste kuit (soleus). Houd nog 20 seconden vast","Wissel van been en herhaal"]'), '$.cues_nl', json('["Beide versies tellen: met gestrekte knie rek je de gastrocnemius (bovenste kuit), met gebogen knie de soleus (onderste kuit). De een vervangt de ander niet","Je hiel blijft de hele tijd op de vloer — komt hij los, ga dan dichter bij de muur staan","💡 Stijve kuiten dragen sterk bij aan fasciitis plantaris, achillespeesklachten en kniepijn. Deze stretch is het waard om elke dag te doen, zeker als je hardloopt"]')), updated_at_ms = 1795305600000 WHERE slug = 'calf-stretch-wall' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand facing a wall, arms extended, hands flat on the wall at chest height. Step one foot back about 60-90 cm, keeping it pointing straight forward and the heel flat on the floor.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Begin op handen en knieën — handen onder je schouders, knieën onder je heupen. Je rug is neutraal, niet hol en niet bol","Adem in: laat je buik zakken en til je borst en stuitje rustig richting het plafond (koe). Kijk iets naar voren","Adem uit: maak je hele rug bol, breng je kin naar je borst en kantel je stuitje naar binnen (kat). Voel de rek over je bovenrug"]'), '$.cues_nl', json('["💡 Laat je ademhaling de beweging sturen — koe op de inademing, kat op de uitademing. Zo koppel je de beweging aan je zenuwstelsel, niet alleen aan je gewrichten","Beweeg langzaam en bewust. Dit is mobiliteitswerk, geen snelle warming-upoefening"]')), updated_at_ms = 1795305600000 WHERE slug = 'cat-cow' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Start on all fours — hands under shoulders, knees under hips. Spine is neutral, no sag or arch.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Start on all fours with your wrists under your shoulders and your knees under your hips, spine neutral","Inhale: let your belly drop toward the floor and gently lift your tailbone and chin (cow)","Exhale: round your spine toward the ceiling and tuck your chin and tailbone (cat)","Repeat slowly"]'), '$.cues', json('["💡 Move with your breath — inhale for cow, exhale for cat.","Move one vertebra at a time — wave through the spine rather than hinging at one spot."]'), '$.steps_nl', json('["Begin op handen en knieën met je polsen onder je schouders en je knieën onder je heupen, rug neutraal","Adem in: laat je buik naar de vloer zakken en til rustig je stuitje en kin op (koe)","Adem uit: maak je rug bol richting het plafond en trek je kin en stuitje in (kat)","Herhaal langzaam"]'), '$.cues_nl', json('["💡 Beweeg mee met je ademhaling — inademen voor koe, uitademen voor kat","Beweeg wervel voor wervel — laat een golf door je rug gaan in plaats van op één punt te knikken"]')), updated_at_ms = 1795305600000 WHERE slug = 'cat-cow-flow' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'On all fours, wrists under shoulders, knees under hips. Neutral spine to start.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Start on all fours with your wrists under your shoulders and your knees under your hips","Inhale: gently let belly drop, lift tailbone and head (Cow)","Exhale: round spine gently toward ceiling, tuck chin and tailbone (Cat)","Move slowly and deliberately, following your breath"]'), '$.cues', json('["Much gentler version — do not overdo the arch","On all fours is comfortable for the belly","Syncing breath with movement calms the nervous system"]'), '$.steps_nl', json('["Begin op handen en knieën met je polsen onder je schouders en je knieën onder je heupen","Adem in: laat je buik rustig zakken en til je stuitje en hoofd op (koe)","Adem uit: maak je rug rustig bol richting het plafond en trek je kin en stuitje in (kat)","Beweeg langzaam en bewust, op het ritme van je ademhaling"]'), '$.cues_nl', json('["Een veel zachtere versie — maak je rug niet te hol","Op handen en knieën is comfortabel voor je buik","Ademhaling en beweging op elkaar afstemmen kalmeert je zenuwstelsel"]')), updated_at_ms = 1795305600000 WHERE slug = 'cat-cow-pregnancy' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'On all fours, wrists under shoulders, knees under hips';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand tall with your feet hip-width apart","Interlace your fingers behind your back (or hold a strap or towel)","Gently squeeze your shoulder blades together","Lift your arms slightly and open your chest upward","Hold for 20–30 seconds while breathing deeply, then lower your arms"]'), '$.cues', json('["Don''t hyperextend neck","Feel the front of chest and shoulders stretch","Perfect for counteracting rounded posture"]'), '$.steps_nl', json('["Sta rechtop met je voeten op heupbreedte","Vouw je vingers achter je rug in elkaar (of houd een band of handdoek vast)","Knijp je schouderbladen zachtjes samen","Til je armen iets op en open je borst naar boven","Houd 20–30 seconden vast en adem diep, laat dan je armen zakken"]'), '$.cues_nl', json('["Trek je nek niet te ver naar achteren.","Voel de rek aan de voorkant van je borst en schouders.","Perfect tegen een ronde houding."]')), updated_at_ms = 1795305600000 WHERE slug = 'chest-opener-arms' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall, feet hip-width';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Lie on your side with your hips stacked and your knees bent to 45°","Keep your feet together","Rotate your top knee upward like a clamshell opening","Hold for 2 seconds at the top","Lower slowly and do 12 reps on each side"]'), '$.cues', json('["Don''t let hips roll back","Think of leading with your knee","Strengthens hips and pelvic stability"]'), '$.steps_nl', json('["Lig op je zij met je heupen recht boven elkaar en je knieën 45° gebogen","Houd je voeten tegen elkaar","Draai je bovenste knie omhoog, zoals een schelp die opengaat","Houd bovenaan 2 seconden vast","Zak langzaam terug en doe 12 herhalingen per kant"]'), '$.cues_nl', json('["Laat je heupen niet naar achteren rollen","Laat je knie de beweging leiden","Versterkt je heupen en de stabiliteit van je bekken"]')), updated_at_ms = 1795305600000 WHERE slug = 'clamshell' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on your side, hips stacked, knees bent to 45°';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Kniel met je rug naar een muur of bank. Schuif je achterste voet omhoog langs de muur tot je wreef en scheen ertegenaan liggen — zo rek je de heupbuiger van dat achterste been","Zet je voorste voet naar voren, plat op de vloer, met je voorste knie recht boven je enkel en je bovenbeen ongeveer evenwijdig aan de vloer","Span de bilspier van je achterste been stevig aan en kantel je bekken iets. Dat zet de rek aan — zonder aangespannen bil voel je het alleen in je knie en niet in je heupbuiger","Houd 60-90 seconden vast en adem rustig door. Wissel van kant"]'), '$.cues_nl', json('["De bilspier van je achterste been aanspannen is geen extraatje: het verplaatst de rek van je knie naar je heupbuiger, waar hij hoort","Houd je bovenlichaam de hele tijd rechtop — leun je naar voren, zet dan je voorste voet verder naar voren","💡 💡 Een van de effectiefste stretches voor je heupbuigers — onmisbaar voor hardlopers, fietsers en iedereen die veel zit. Minimaal 60-90 seconden per kant om resultaat te zien"]')), updated_at_ms = 1795305600000 WHERE slug = 'couch-stretch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Kneel with your back to a wall or sofa. Slide your rear foot up the wall so the top of your foot and shin are resting against it — this stretches the hip flexor of that rear leg.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand tall with your arms relaxed at your sides","Bring your right arm straight across your chest","Use your left hand or forearm to gently press your right arm closer to your chest","Hold the stretch for 20–30 seconds","Release your arm and repeat on the other side"]'), '$.cues', json('["Keep shoulder down, away from ear","Don''t rotate — stay square","Good for carrying-related shoulder tension"]'), '$.steps_nl', json('["Sta rechtop met je armen ontspannen langs je lichaam","Breng je rechterarm gestrekt voor je borst langs","Duw je rechterarm met je linkerhand of linkeronderarm zachtjes dichter naar je borst","Houd de rek 20–30 seconden vast","Laat je arm los en herhaal aan de andere kant"]'), '$.cues_nl', json('["Houd je schouder laag, weg van je oor","Niet meedraaien — blijf recht naar voren staan","Goed tegen schouderspanning door veel tillen en dragen"]')), updated_at_ms = 1795305600000 WHERE slug = 'cross-body-shoulder-stretch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit or stand tall with your shoulders relaxed","Place your fingertips just inside your hip bones","Exhale slowly and feel the muscle under your fingers gently tighten (do not suck in or push out)","Hold this gentle engagement for 5 breaths","Release completely, then repeat"]'), '$.cues', json('["Imagine zipping up low-rise jeans very gently","Don''t hold breath","Foundation exercise for all postnatal core work"]'), '$.steps_nl', json('["Zit of sta rechtop met ontspannen schouders","Leg je vingertoppen net aan de binnenkant van je heupbotten","Adem langzaam uit en voel de spier onder je vingers zachtjes aanspannen (niet intrekken, niet naar buiten duwen)","Houd die lichte spanning 5 ademhalingen vast","Laat helemaal los en herhaal"]'), '$.cues_nl', json('["Stel je voor dat je heel voorzichtig een laag uitgesneden spijkerbroek dichtritst","Houd je adem niet in","De basisoefening voor alle core-training na de bevalling"]')), updated_at_ms = 1795305600000 WHERE slug = 'deep-core-activation' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit or stand tall';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta met je voeten iets breder dan schouderbreedte, tenen 30-45 graden naar buiten. Zak in een volledige squat — heupen lager dan je knieën — en blijf onderin zitten","Duw je ellebogen tegen de binnenkant van je knieën om ze zachtjes naar buiten te drukken. Houd je borst omhoog en je rug lang. Je hielen blijven plat op de vloer","Houd vast voor de opgegeven tijd en adem rustig door. Komen je hielen omhoog, leg er dan een opgevouwen handdoek of kleine halterschijf onder terwijl je aan je enkelmobiliteit werkt"]'), '$.cues_nl', json('["Deze houding is een basis van menselijke mobiliteit — voelt hij oncomfortabel, dan is dat een signaal dat je heupen, enkels of bovenrug mobiliteitswerk nodig hebben","Je knieën openduwen met je ellebogen is een aanwijzing én een stretch — je opent je heupen actief van binnenuit","💡 💡 Oefen dagelijks en houd 60 seconden vast. De buiging van je enkel is meestal de beperkende factor — kuiten rekken en verhoogde hielen overbruggen het gat terwijl je eraan werkt"]')), updated_at_ms = 1795305600000 WHERE slug = 'deep-squat-hold' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with feet slightly wider than shoulder-width, toes turned out 30-45 degrees. Lower into a full squat — hips below knees — and hold the bottom position.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Start on all fours, tuck your toes and push your hips up and back","Form an inverted V shape with your body","Press your heels toward the floor","Alternate bending each knee (pedalling)","Lower your knees back to the floor to finish"]'), '$.cues', json('["Spread fingers wide","Relax head between arms"]'), '$.steps_nl', json('["Begin op handen en knieën, zet je tenen neer en duw je heupen omhoog en naar achteren","Vorm met je lichaam een omgekeerde V","Duw je hielen richting de vloer","Buig om en om je knieën (fietsen).","Zet je knieën terug op de vloer om af te sluiten"]'), '$.cues_nl', json('["Spreid je vingers wijd.","Laat je hoofd ontspannen tussen je armen hangen."]')), updated_at_ms = 1795305600000 WHERE slug = 'downward-dog' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'From all fours, tuck toes, push hips up and back';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit or stand in a comfortable, upright position","Take a natural breath in","As you exhale slowly through pursed lips, feel your lower belly gently drawing inward","Add a light pelvic floor lift on the exhale","Repeat for 8–10 breaths"]'), '$.cues', json('["Exhale should be 4–6 seconds","Don''t force — let exhale do the work","The exhale IS the core exercise"]'), '$.steps_nl', json('["Ga comfortabel rechtop zitten of staan","Adem rustig in.","Adem langzaam uit door getuite lippen en voel je onderbuik zachtjes naar binnen trekken.","Til bij de uitademing je bekkenbodem licht op.","Herhaal 8–10 ademhalingen."]'), '$.cues_nl', json('["Je uitademing duurt 4–6 seconden.","Niet forceren: laat de uitademing het werk doen.","De uitademing ÍS de core-oefening."]')), updated_at_ms = 1795305600000 WHERE slug = 'exhalation-core-engagement' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit or stand';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Extend your right arm straight in front of you with your palm facing up","Use your left hand to gently pull your fingers down toward the floor","Hold for 20 seconds and feel the stretch along the underside of your forearm","Turn your palm down, gently pull your fingers up and hold for 20 seconds","Switch arms and repeat"]'), '$.cues', json('["Gentle pressure only","Helps with wrist swelling in pregnancy (carpal tunnel)","Essential for new parents carrying a baby"]'), '$.steps_nl', json('["Strek je rechterarm recht voor je uit met je handpalm naar boven","Trek met je linkerhand je vingers zachtjes omlaag richting de vloer","Houd 20 seconden vast en voel de rek aan de onderkant van je onderarm","Draai je handpalm naar beneden, trek je vingers zachtjes omhoog en houd 20 seconden vast","Wissel van arm en herhaal"]'), '$.cues_nl', json('["Alleen zachte druk","Helpt bij gezwollen polsen tijdens de zwangerschap (carpaletunnelklachten)","Onmisbaar voor kersverse ouders die veel een baby dragen"]')), updated_at_ms = 1795305600000 WHERE slug = 'forearm-wrist-stretch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Extend right arm straight, palm facing up';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Lie on your back with your knees bent","Cross your right ankle over your left knee","Flex your right foot","Stay here, or reach through your legs to hold your left thigh","Gently draw your left leg toward your chest","Hold for 30–60 seconds, then switch sides"]'), '$.cues', json('["Flex the top foot to protect the knee","A figure-four stretch lying down","Excellent for sciatic nerve tension"]'), '$.steps_nl', json('["Lig op je rug met je knieën gebogen","Leg je rechterenkel over je linkerknie","Trek de tenen van je rechtervoet naar je toe","Blijf zo liggen, of reik tussen je benen door en pak je linkerdij vast","Trek je linkerbeen rustig naar je borst","Houd 30–60 seconden vast en wissel dan van kant"]'), '$.cues_nl', json('["Houd je bovenste voet aangespannen om je knie te beschermen","Een figuur-4 stretch, maar dan liggend","Heel fijn bij spanning rond de heupzenuw"]')), updated_at_ms = 1795305600000 WHERE slug = 'glute-piriformis-stretch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 6 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on back, knees bent';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Lie on your back with your knees bent","Exhale and gently brace your core","Slowly slide one heel along the floor until your leg is nearly straight","Slide your heel back in to the start position","Alternate legs and do 8 reps per side"]'), '$.cues', json('["Keep lower back still throughout","Breathe continuously","Great early postnatal core reconnection exercise"]'), '$.steps_nl', json('["Lig op je rug met je knieën gebogen","Adem uit en span je core licht aan","Schuif één hiel langzaam over de vloer tot je been bijna gestrekt is","Schuif je hiel terug naar de beginpositie","Wissel van been en doe 8 herhalingen per kant"]'), '$.cues_nl', json('["Houd je onderrug de hele tijd stil","Blijf doorademen","Fijne oefening om na de bevalling weer contact te maken met je core"]')), updated_at_ms = 1795305600000 WHERE slug = 'heel-slides' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on back, knees bent';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Step your right foot forward into a lunge","Lower your left knee toward the floor (or stay standing)","Shift your weight forward until you feel a stretch in your left hip","Hold the stretch, then switch sides"]'), '$.cues', json('["Tall spine","Squeeze back glute for deeper stretch"]'), '$.steps_nl', json('["Stap met je rechtervoet naar voren in een uitvalspas","Laat je linkerknie richting de vloer zakken (of blijf staan)","Breng je gewicht naar voren tot je een rek in je linkerheup voelt","Houd de rek vast en wissel dan van kant"]'), '$.cues_nl', json('["Houd je rug lang","Span je achterste bilspier aan voor een diepere rek"]')), updated_at_ms = 1795305600000 WHERE slug = 'hip-flexor-stretch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Step right foot forward into lunge';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit on a chair with a soft ball, rolled towel or pillow between your knees","Exhale and gently squeeze your knees together","Contract your pelvic floor at the same time as you squeeze","Hold for 5 seconds, then release fully","Repeat 10 times"]'), '$.cues', json('["No ball? Just imagine squeezing","Coordinate with pelvic floor lift","Good seated desk-break exercise"]'), '$.steps_nl', json('["Ga op een stoel zitten met een zachte bal, opgerolde handdoek of kussen tussen je knieën","Adem uit en knijp je knieën zachtjes naar elkaar toe","Span tegelijk met het knijpen je bekkenbodem aan","Houd 5 seconden vast en laat dan helemaal los","Herhaal 10 keer"]'), '$.cues_nl', json('["Geen bal? Doe dan alsof je knijpt","Combineer het met het optillen van je bekkenbodem","Goede oefening voor een pauze achter je bureau"]')), updated_at_ms = 1795305600000 WHERE slug = 'inner-thigh-squeeze' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit on chair with a soft ball, rolled towel, or pillow between knees';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit comfortably and imagine your pelvic floor is an elevator","Go to floor 1 with a gentle squeeze","Rise to floor 2 by squeezing a little more","Rise to floor 3 with your maximum gentle lift","Slowly descend floor by floor","Rest completely before repeating"]'), '$.cues', json('["No rushing — slow and deliberate","Notice each level of engagement","Great for body awareness"]'), '$.steps_nl', json('["Ga comfortabel zitten en stel je voor dat je bekkenbodem een lift is","Ga naar verdieping 1 door licht aan te spannen","Ga naar verdieping 2 door iets meer aan te spannen","Ga naar verdieping 3 met je hoogste, nog steeds zachte spanning","Zak langzaam weer af, verdieping voor verdieping","Ontspan helemaal voor je herhaalt"]'), '$.cues_nl', json('["Niet haasten — langzaam en bewust","Voel elk niveau van aanspanning","Goed voor je lichaamsbewustzijn"]')), updated_at_ms = 1795305600000 WHERE slug = 'kegel-elevator' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 7 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit comfortably';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga comfortabel zitten, staan of liggen","Zoek je bekkenbodemspieren op (de spieren waarmee je het plassen ophoudt)","Span ze aan en til ze omhoog","Houd 5–10 seconden vast","Laat langzaam los en neem even lang rust","Herhaal 10 keer"]'), '$.cues_nl', json('["Houd je adem niet in","Houd je billen en bovenbenen ontspannen","Kwaliteit boven kwantiteit"]')), updated_at_ms = 1795305600000 WHERE slug = 'kegel-hold' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 6 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit, stand, or lie comfortably';
