UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand with your feet hip-width apart","Hinge forward from your hips","Let your arms hang or hold your elbows","Hold and breathe into the stretch, then roll up slowly to standing"]'), '$.cues', json('["Bend knees if needed","Relax neck completely"]'), '$.steps_nl', json('["Sta met je voeten op heupbreedte","Buig naar voren vanuit je heupen","Laat je armen hangen of pak je ellebogen vast","Houd vast en adem naar de rek toe, rol daarna langzaam op tot je staat"]'), '$.cues_nl', json('["Buig je knieën als dat nodig is","Ontspan je nek helemaal"]')), updated_at_ms = 1795305600000 WHERE slug = 'standing-forward-fold' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand, feet hip-width';
