UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta op één been en steun met je vrije hand op een muur, rugleuning of deurpost voor balans. Breng je gewicht stevig op je standvoet","Buig je andere knie en breng je hiel naar je bil. Reik met de hand aan dezelfde kant naar achteren en pak je enkel vast — niet je voet. Kom je er niet bij, gebruik dan een band of handdoek","Trek je hiel rustig dichter naar je bil en duw je heup aan de rekkant iets naar voren. Je gebogen knie wijst recht omlaag en zwaait niet naar buiten","Houd 20-30 seconden vast en adem rustig door, laat dan langzaam los en wissel van kant. Forceer nooit — laat de rek vanzelf komen"]'), '$.cues_nl', json('["Knieën bij elkaar is hier de belangrijkste aanwijzing — de rek wordt veel kleiner als je gebogen knie wegdraait van je standbeen","Sta rechtop met beide heupen op gelijke hoogte — trek je één heup op, dan klopt de lijn van je bovenbeen niet meer en neemt de rek af","Je heup aan de rekkant iets naar voren duwen rekt ook je heupbuiger mee — waardevol voor iedereen die lang zit"]')), updated_at_ms = 1795305600000 WHERE slug = 'standing-quad-stretch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand on one leg — rest your free hand on a wall, chair back, or doorframe for balance. Shift your weight solidly onto the supporting foot.';
