UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit or stand comfortably and name 5 things you can see","Notice 4 things you can physically feel","Listen for 3 things you can hear","Notice 2 things you can smell","Notice 1 thing you can taste","Finish with one long slow breath"]'), '$.cues', json('["Also called 5-4-3-2-1 grounding","Brings you back to the present moment","Can help when you feel anxious during pregnancy"]'), '$.steps_nl', json('["Ga comfortabel zitten of staan en benoem 5 dingen die je ziet","Merk 4 dingen op die je lichamelijk voelt","Luister naar 3 dingen die je hoort","Merk 2 dingen op die je ruikt","Merk 1 ding op dat je proeft","Sluit af met één lange, langzame ademhaling"]'), '$.cues_nl', json('["Ook wel 5-4-3-2-1-gronding genoemd","Brengt je terug naar het hier en nu","Kan helpen als je je angstig voelt tijdens de zwangerschap"]')), updated_at_ms = 1795305600000 WHERE slug = '5-senses-grounding' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 6 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Notice 5 things you can see';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit comfortably and raise your right hand to your face","Close your right nostril with your right thumb and inhale through the left","Close your left nostril with your ring finger, release your thumb and exhale through the right","Inhale through the right nostril","Close the right nostril, release the left and exhale through the left","That is one cycle — repeat 5–10 times, then lower your hand and breathe normally"]'), '$.cues', json('["Keep the breath slow and even on both sides","Many people find it calming and good for focus","Avoid retention (holding) during pregnancy"]'), '$.steps_nl', json('["Ga comfortabel zitten en breng je rechterhand naar je gezicht","Sluit je rechterneusgat met je rechterduim en adem in door links","Sluit je linkerneusgat met je ringvinger, laat je duim los en adem uit door rechts","Adem in door je rechterneusgat","Sluit rechts, laat links los en adem uit door links","Dat is één cyclus — herhaal 5–10 keer, laat dan je hand zakken en adem gewoon door"]'), '$.cues_nl', json('["Houd je adem aan beide kanten rustig en gelijkmatig","Veel mensen worden er rustig en geconcentreerd van","Houd je adem niet vast tijdens de zwangerschap"]')), updated_at_ms = 1795305600000 WHERE slug = 'alternate-nostril-breathing' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 6 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit comfortably, right hand raised to face';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga zitten of liggen met gestrekte benen, of leg je voeten omhoog op een kussen","Buig je voeten — trek je tenen naar je toe","Strek je voeten — duw je tenen van je af","Wissel af in een rustig ritme, 20 tot 30 keer","Draai daarna met je enkels cirkels in beide richtingen"]'), '$.cues_nl', json('["Zet de kuitspierpomp aan het werk","Onmisbaar tijdens de zwangerschap om trombose te voorkomen","Doe dit elke 30 tot 60 minuten als je lang zit"]')), updated_at_ms = 1795305600000 WHERE slug = 'ankle-pumps' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit or lie with legs extended, or elevate feet on a pillow';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga comfortabel liggen","Sluit je ogen","Breng je aandacht langzaam van je voeten omhoog door je lichaam","Merk op wat je voelt, zonder oordeel"]'), '$.cues_nl', json('["5-10 minuten is ideaal","Kan ook in bed"]')), updated_at_ms = 1795305600000 WHERE slug = 'body-scan-meditation' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie down comfortably';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit or lie comfortably","Inhale for 4 counts","Hold for 4 counts","Exhale for 4 counts","Hold empty for 4 counts","Repeat 4-6 cycles"]'), '$.cues', json('["Used by elite athletes for stress control","Eyes closed if comfortable"]'), '$.steps_nl', json('["Ga comfortabel zitten of liggen","Adem in 4 tellen in","Houd 4 tellen vast","Adem in 4 tellen uit","Houd 4 tellen vast met lege longen","Herhaal 4-6 cycli"]'), '$.cues_nl', json('["Topsporters gebruiken dit om stress te beheersen","Ogen dicht als dat prettig voelt"]')), updated_at_ms = 1795305600000 WHERE slug = 'box-breathing' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Inhale for 4 counts';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga comfortabel zitten met je ogen dicht","Adem vanzelf — stuur je adem niet","Tel elke uitademing, van 1 tot 10","Ben je bij 10, begin dan weer bij 1","Raak je de tel kwijt, begin dan gewoon weer bij 1"]'), '$.cues_nl', json('["Een eenvoudig anker voor je aandacht","De tel kwijtraken is normaal — begin opnieuw, zonder oordeel","5 minuten is ruim voldoende"]')), updated_at_ms = 1795305600000 WHERE slug = 'breath-counting' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit comfortably, eyes closed';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Kniel op een mat en breng je heupen naar achteren richting je hielen. Zet je knieën zo wijd als prettig voelt of houd ze tegen elkaar — beide varianten werken","Strek je armen naar voren over de vloer en leg je voorhoofd op de mat. Laat je borst naar de grond zakken","Adem langzaam en diep. Laat bij elke uitademing je heupen iets verder naar achteren zakken en je rug langer worden"]'), '$.cues_nl', json('["Knieën wijder geeft een diepere heupstretch en meer ruimte voor je romp. Knieën tegen elkaar legt de nadruk op de stretch van je onderrug","Adem naar je onderrug — je voelt hem bij elke inademing zijwaarts uitzetten. Dit is passieve decompressie","💡 Gebruik dit als reset tussen zware sets of als laatste houding van je sessie. Je kunt hier niet verkeerd rusten"]')), updated_at_ms = 1795305600000 WHERE slug = 'childs-pose' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Kneel on a mat and sit your hips back toward your heels. Separate your knees as wide as comfortable or keep them together — both variations work.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga comfortabel zitten","Rol je tong tot een buisje (lukt dat niet: tanden iets van elkaar, tong erachter)","Adem in door je gerolde tong of open mond — voel de koele lucht","Sluit je mond en adem uit door je neus","Herhaal 6–10 keer"]'), '$.cues_nl', json('["Werkt echt verkoelend — fijn bij warm weer of misselijkheid","Werkt ook als je je tong niet kunt rollen","Helpt als je het tijdens de zwangerschap snel te warm hebt"]')), updated_at_ms = 1795305600000 WHERE slug = 'cooling-breath' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit comfortably';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Jog of wandel 5 minuten rustig uit (tempo zone 1)","Doe statische stretches voor de grote spiergroepen (quadriceps, hamstrings, kuiten, heupbuigers)"]'), '$.cues_nl', json('["Lage intensiteit","Houd elke stretch 20–30 s vast","Blijf diep doorademen"]')), updated_at_ms = 1795305600000 WHERE slug = 'cooling-down' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 2 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Easy jog or walk for 5 minutes (zone 1 pace)';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Wrijf je handpalmen 10 seconden stevig tegen elkaar tot ze warm zijn","Leg je warme handpalmen als een kommetje over je gesloten ogen — geen druk op je oogbollen","Adem rustig en laat je ogen in het donker helemaal ontspannen","Houd 60–90 seconden vast","Herhaal 2–3 keer"]'), '$.cues_nl', json('["Verlicht vermoeide ogen na schermwerk","De warmte en het donker werken heel rustgevend","Doe een paar druppels lavendel op je handpalmen voor extra rust"]')), updated_at_ms = 1795305600000 WHERE slug = 'eye-palming' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Rub palms together briskly for 10 seconds until warm';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op de vloer zitten met de roller onder je kuiten. Zet je handen achter je voor steun","Til je heupen op en rol van je enkel tot net onder je knie. Blijf even op strakke plekken","Leg één enkel over de andere om de druk op één kuit te vergroten"]'), '$.cues_nl', json('["💡 Draai je voet naar binnen en naar buiten om je kuitspier onder verschillende hoeken te raken","Onmisbaar na het hardlopen of fietsen — strakke kuiten dragen bij aan hiel- en kniepijn"]')), updated_at_ms = 1795305600000 WHERE slug = 'foam-roll-calves' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Sit on the floor, roller under your calves. Hands behind you for support.';
