UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op de vloer zitten met de roller onder de achterkant van één bovenbeen. Handen achter je voor steun, je andere been erover gekruist voor extra druk","Rol van net boven je knie tot net onder je bil en blijf even op strakke plekken","Draai je been naar binnen en naar buiten om verschillende vezels te raken"]'), '$.cues_nl', json('["💡 Het grootste deel van je hamstring zit in het midden van je bovenbeen — besteed daar de meeste tijd","Eén been over het andere kruisen verdubbelt de druk — gebruik dit als je het nodig hebt"]')), updated_at_ms = 1795305600000 WHERE slug = 'foam-roll-hamstrings' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Sit on the floor, roller under the back of one thigh. Hands behind for support, other leg crossed over for extra pressure.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op je buik liggen. Leg de foamroller onder je rechterlies (net onder je bekken, waar je heupbuiger overgaat in je bovenbeen)","Steun op je onderarmen en verken langzaam het gebied net binnen en onder je heupbot","Blijf op strakke plekken en adem door. Buig en strek rustig je knie om de spanning actief los te maken"]'), '$.cues_nl', json('["💡 Dit is een klein, gericht gebied — beweeg langzaam, het weefsel ligt diep","Veel waard voor hardlopers, fietsers en iedereen die lang zit"]')), updated_at_ms = 1795305600000 WHERE slug = 'foam-roll-hip-flexors' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie face down. Position the foam roller under your right hip crease area (just below the pelvis, where the hip flexor meets the thigh).';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op je zij liggen met de foamroller onder de buitenkant van je bovenbeen. Steun op één onderarm, je bovenste voet op de vloer voor stabiliteit","Rol langzaam van net boven je knie tot net onder je heup — rustig aan, dit gebied is vaak erg gevoelig","Blijf op strakke plekken, adem door en laat het weefsel ontspannen voordat je verdergaat"]'), '$.cues_nl', json('["💡 De IT-band zelf heeft geen directe druk nodig — je richt je op de spieren die eraan vastzitten","Te pijnlijk? Zet beide voeten op de vloer om de druk te verminderen"]')), updated_at_ms = 1795305600000 WHERE slug = 'foam-roll-it-band' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on your side, foam roller under your outer thigh. Support yourself on one forearm, top foot on the floor for stability.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op je zij liggen met de roller onder je oksel. Strek je onderste arm boven je hoofd","Rol langzaam van net onder je oksel tot halverwege je ribbenkast en blijf even op strakke plekken","Draai iets naar voren om de serratus en de achterkant van je schouder te bereiken. Wissel van kant"]'), '$.cues_nl', json('["💡 Strakke lats trekken je schouder naar voren en beperken je bereik boven je hoofd — hier rollen levert veel op","Strek en buig je elleboog terwijl je op een strakke plek ligt om de spanning actief los te maken"]')), updated_at_ms = 1795305600000 WHERE slug = 'foam-roll-lats' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on your side, roller under your armpit area. Extend the bottom arm overhead.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op je buik liggen met de foamroller onder je bovenbenen. Steun op je onderarmen","Rol langzaam van de bovenkant van je knie tot net onder je heup en blijf 10–20 seconden op strakke plekken","Draai 30° naar één kant voor de buitenkant van je quadriceps (vastus lateralis), daarna naar de binnenkant"]'), '$.cues_nl', json('["💡 Adem door op strakke plekken in plaats van eraf te rollen","Laat elke baan iets overlappen — systematisch werken is beter dan willekeurig rollen"]')), updated_at_ms = 1795305600000 WHERE slug = 'foam-roll-quads' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie face down, foam roller under your thighs. Support yourself on your forearms.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga voor de foamroller zitten en leun achterover tot hij dwars onder het midden van je rug ligt","Ondersteun je hoofd met je handen. Strek je rustig over de roller en open je borst","Verplaats de roller stukje voor stukje van het midden van je rug naar de bovenkant van je schouderbladen"]'), '$.cues_nl', json('["💡 Rol niet over je onderrug of nek — alleen het midden en bovenste deel van je rug","Een van de beste tegenhangers van een bureauhouding — neem hier extra tijd voor"]')), updated_at_ms = 1795305600000 WHERE slug = 'foam-roll-upper-back' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Sit in front of the foam roller and lean back onto it so it''s positioned across your mid-back.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand with your feet shoulder-width apart and your hands on your hips","Make 10 large circles with your hips clockwise","Reverse direction for 10 more circles"]'), '$.cues', json('["Move slowly","Great after sitting long periods"]'), '$.steps_nl', json('["Sta met je voeten op schouderbreedte en je handen op je heupen","Maak 10 grote cirkels met je heupen met de klok mee","Draai 10 cirkels de andere kant op"]'), '$.cues_nl', json('["Beweeg langzaam","Fijn na lang zitten"]')), updated_at_ms = 1795305600000 WHERE slug = 'gentle-hip-circles' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand feet shoulder-width, hands on hips';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga comfortabel zitten met je ogen dicht","Denk aan 3 concrete dingen waar je vandaag dankbaar voor bent","Blijf bij elk ding 10–15 seconden bij het gevoel","Merk op of je ergens warmte of ontspanning in je lichaam voelt","Open langzaam je ogen"]'), '$.cues_nl', json('["Hoe concreter, hoe beter — ''mijn warme koffie'' en niet alleen ''koffie''","Onderzoek laat zien dat dit cortisol verlaagt","Een krachtig hulpmiddel voor emotioneel herstel"]')), updated_at_ms = 1795305600000 WHERE slug = 'gratitude-reflection' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit comfortably with eyes closed';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op je rug liggen. Trek beide knieën naar je borst en open ze dan wijd richting je oksels","Buig je voeten en pak de buitenranden van je voeten vast (of je enkels of schenen als dat nodig is)","Trek rustig naar beneden en breng je knieën naar de vloer naast je romp. Wieg van links naar rechts als dat goed voelt"]'), '$.cues_nl', json('["💡 Dit is een herstellende houding — laat de zwaartekracht het werk doen en blijf er lang in","Een van de beste heupopeners na een hardloop- of beentraining"]')), updated_at_ms = 1795305600000 WHERE slug = 'happy-baby-pose' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on your back. Draw both knees toward your chest, then open them wide toward the armpits.';
