UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Sit or kneel comfortably, or find your most comfortable position","Inhale slowly and deeply through your nose for 4–6 counts","Exhale long and controlled through a softly open mouth for 6–8 counts","On the exhale, let your jaw, face, shoulders and pelvic floor all release","Repeat for 5–10 minutes"]'), '$.cues', json('["This IS the most useful thing to practice in T3","Exhale is the tool — the release is everything","Practice daily from 36 weeks"]'), '$.steps_nl', json('["Ga comfortabel zitten of knielen, of zoek de houding die voor jou het prettigst is","Adem langzaam en diep in door je neus in 4–6 tellen","Adem lang en beheerst uit door een zacht geopende mond in 6–8 tellen","Laat bij de uitademing je kaak, gezicht, schouders en bekkenbodem helemaal los","Herhaal 5–10 minuten"]'), '$.cues_nl', json('["Dit is hét nuttigste om te oefenen in het derde trimester","De uitademing is je gereedschap — loslaten is alles","Oefen dagelijks vanaf 36 weken"]')), updated_at_ms = 1795305600000 WHERE slug = 'labour-breathing-prep' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit or kneel comfortably, or find your most comfortable position';
