UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga comfortabel zitten of liggen","Breng je aandacht naar je voeten — wat merk je op? Temperatuur, druk, gevoel","Ga langzaam met je aandacht omhoog: enkels, kuiten, knieën, bovenbenen...","Ga zo door je hele lichaam tot aan je kruin","Merk op zonder oordeel — je kunt niets goed of fout voelen"]'), '$.cues_nl', json('["Lichter dan een bodyscan — alleen opmerken","3–5 minuten is ruim voldoende","Goede oefening om je bewust te worden van je houding"]')), updated_at_ms = 1795305600000 WHERE slug = 'mindful-body-check' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit or lie comfortably';
