UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand in front of the munitiekist (ammunition crate) on the floor and grip the handles","Lift the crate from the floor and carry it 25 metres to the lift table","Place the crate on the table at shoulder height (115-135 cm, adjusted to body height)","Lift the crate from the table and carry it 25 metres back","Lower the crate to the floor — this completes one repetition","Start a new repetition every 25 seconds; do 2 sets of 10 reps with 30 s rest between sets"]'), '$.cues', json('["Test weights: 20 kg (Basis/K1), 20+30 kg (K2/K4), 20+30+40 kg (K3/K5/K6)","Arms horizontal at shoulder height when gripping handles","Train with the weight appropriate for your cluster target"]'), '$.steps_nl', json('["Ga voor de munitiekist op de vloer staan en pak de handgrepen vast","Til de kist van de vloer en draag hem 25 meter naar de tiltafel","Zet de kist op de tafel op schouderhoogte (115-135 cm, afgestemd op je lichaamslengte)","Til de kist van de tafel en draag hem 25 meter terug","Zet de kist op de vloer — dat is één herhaling","Start elke 25 seconden een nieuwe herhaling; doe 2 sets van 10 herhalingen met 30 s rust tussen de sets"]'), '$.cues_nl', json('["Testgewichten: 20 kg (Basis/K1), 20+30 kg (K2/K4), 20+30+40 kg (K3/K5/K6)","Armen horizontaal op schouderhoogte als je de handgrepen vastpakt","Train met het gewicht dat past bij je clusterdoel"]')), updated_at_ms = 1795305600000 WHERE slug = 'til-draagtest-full-exercise' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 7 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 5 AND json_extract(instructions_json, '$.steps[0]') = 'Lift munitiekist from floor';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand in front of the munitiekist (ammunition crate) on the floor","Grip the handles firmly — arms horizontal at shoulder height when extended","Explosively lift the crate from the floor to shoulder height in one fast movement","Place the crate on the lift table at shoulder height (115-135 cm, adjusted to body height)","Lower the crate with control","Do 5 sets of 10 s with 2 min rest"]'), '$.cues', json('["Fast explosive execution","Test weights: 20 kg (Basis/K1), 30 kg (K2/K4), 40 kg (K3/K5/K6)","New repetition every 25 seconds in the actual test"]'), '$.steps_nl', json('["Ga voor de munitiekist op de vloer staan","Pak de handgrepen stevig vast — armen horizontaal op schouderhoogte als ze gestrekt zijn","Til de kist explosief van de vloer naar schouderhoogte in één snelle beweging","Zet de kist op de tiltafel op schouderhoogte (115-135 cm, afgestemd op je lichaamslengte)","Laat de kist gecontroleerd zakken","Doe 5 sets van 10 s met 2 min rust"]'), '$.cues_nl', json('["Snel en explosief uitvoeren","Testgewichten: 20 kg (Basis/K1), 30 kg (K2/K4), 40 kg (K3/K5/K6)","In de echte test start elke 25 seconden een nieuwe herhaling"]')), updated_at_ms = 1795305600000 WHERE slug = 'til-draagtest-gewicht-plaatsen-naar-heupen' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 5 AND json_extract(instructions_json, '$.steps[0]') = 'Starting position: munitiekist (ammunition crate) on the floor';
