UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Hang een weerstandsband over de stang en zet één knie of voet in de lus","Pak de stang vast op schouderbreedte","Trek jezelf op tot je kin boven de stang komt","Zak gecontroleerd terug"]'), '$.cues_nl', json('["Een dikkere band helpt meer — kies een dunnere naarmate je sterker wordt","Borst naar de stang, niet je kin eroverheen rekken","💡 Houd je ribben omlaag, zodat het geen zwaai wordt"]')), updated_at_ms = 1795305600000 WHERE slug = 'assisted-pull-up-band' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Loop a band over the bar and put one knee or foot in the loop.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Stel het hulpgewicht in — meer gewicht betekent meer hulp","Kniel of sta op het steunkussen en pak de handgrepen vast","Trek jezelf op tot je kin boven de stang komt","Zak gecontroleerd terug"]'), '$.cues_nl', json('["Verminder de hulp naarmate je sterker wordt","Elke herhaling de volledige beweging","💡 Zo train je de echte beweging lang voordat je een herhaling zonder hulp kunt"]')), updated_at_ms = 1795305600000 WHERE slug = 'assisted-pull-up-machine' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Set the assistance weight — more weight means more help.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta met je voeten op schouderbreedte; leg bij een variant met gewicht de stang op je bovenste trapezius","Duw je heupen naar achteren en zak, met je borst rechtop en je core aangespannen","Zak tot je bovenbenen minstens evenwijdig aan de vloer zijn","Duw door je hele voet — hiel en middenvoet — om omhoog te komen"]'), '$.cues_nl', json('["Je knieën wijzen de hele beweging naar buiten, boven je tweede teen","Span voor elke herhaling je core aan alsof je een stomp in je maag krijgt","💡 Eerst met lichaamsgewicht: beheers de beweging voordat je gewicht toevoegt. Komen je hielen los = stijve enkels — leg er iets onder"]')), updated_at_ms = 1795305600000 WHERE slug = 'back-squat' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with feet shoulder-width apart; for a loaded version rest the bar across your upper traps';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op het midden van de band staan, voeten op heupbreedte","Buig vanuit je heupen ongeveer 45° naar voren met een rechte rug, een uiteinde van de band in elke hand","Trek beide handen naar je onderste ribben","Zak gecontroleerd terug tot je armen gestrekt zijn"]'), '$.cues_nl', json('["Houd je rug recht — buig vanuit je heupen, niet vanuit je rug","Je ellebogen strijken langs je zij","💡 Zet je voeten wijder op de band voor meer weerstand"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-bent-over-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand on the middle of the band, feet hip-width.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op het midden van de band staan, voeten op heupbreedte. Houd in elke hand een uiteinde vast met een onderhandse greep, armen gestrekt langs je lichaam","Curl beide handen naar je schouders en houd je ellebogen tegen je zij. Houd de hele beweging gelijkmatige spanning","Zak langzaam — de weerstand blijft tot helemaal onderaan, anders dan bij losse gewichten"]'), '$.cues_nl', json('["💡 De band geeft de meeste weerstand als hij maximaal is uitgerekt en bijna geen aan het begin — het omgekeerde van een dumbbell. Ideaal voor bicepskracht aan het einde van de beweging","Houd je ellebogen op hun plek. Schuiven ze naar voren, dan verschuift het werk weg van je biceps"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-bicep-curl' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand on the center of the band with feet hip-width. Hold one end in each hand with an underhand grip, arms extended at your sides.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Anchor a band low behind your head. Lie on your back holding it with straight arms over your chest","Bring your knees over your hips with your shins parallel to the floor","Extend one leg away while holding the band steady","Bring the leg back and alternate sides"]'), '$.cues', json('["The band pulls your arms back — resist it","Lower back stays flat on the floor","💡 Adds load to a movement that gets easy fast"]'), '$.steps_nl', json('["Maak een band laag achter je hoofd vast. Ga op je rug liggen en houd hem met gestrekte armen boven je borst","Breng je knieën boven je heupen met je schenen evenwijdig aan de vloer","Strek één been van je af terwijl je de band stilhoudt","Breng je been terug en wissel van kant"]'), '$.cues_nl', json('["De band trekt je armen naar achteren — bied weerstand","Je onderrug blijft plat op de vloer","💡 Maakt een beweging zwaarder die snel te makkelijk wordt"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-dead-bug' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Anchor a band low behind your head. Lie on your back holding it with straight arms over your chest.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Maak de band vast op gezichtshoogte. Houd in elke hand een uiteinde vast met een bovenhandse greep, armen naar voren gestrekt","Trek de band naar je gezicht en stuur je ellebogen wijd en hoog. Je handen eindigen ter hoogte van je oren, je ellebogen boven schouderhoogte","Ga gecontroleerd terug naar de start. Bied weerstand als de band je handen weer naar elkaar trekt"]'), '$.cues_nl', json('["💡 Face pulls zijn het tegengif voor te veel drukoefeningen — ze brengen je schouder in balans en trainen de achterste schouderspier die de meeste mensen verwaarlozen","Ellebogen hoog en wijd is de belangrijkste aanwijzing. Zakken je ellebogen, dan doe je een row en geen face pull"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-face-pull' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Anchor the band at face height. Hold one end in each hand with an overhand grip, arms extended forward.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Maak de band vast op enkelhoogte en leg het andere uiteinde om één enkel. Sta met het ankerpunt naast of voor je en houd je zo nodig vast aan een muur voor balans","Til je buitenste been gestrekt zijwaarts op tegen de band in. Je heup stuurt de beweging — niet je onderrug","Zak langzaam — bied weerstand als de band je been naar binnen trekt. Doe alle herhalingen en wissel dan van kant"]'), '$.cues_nl', json('["💡 Dit traint de gluteus medius — de heupstabilisator die bepalend is voor de stand van je knie bij hardlopen, landen en squatten","Kantel je romp niet als je je been optilt. Leun je, dan is de belasting van je heup naar je rug verschoven"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-hip-abduction-standing' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Anchor the band at ankle height. Loop the other end around one ankle. Stand with the anchor to your side or in front, holding a wall for balance if needed.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Maak een band vast boven hoofdhoogte — een deuranker of het scharnier van een dichte deur werkt","Kniel of zit rechtop, armen boven je hoofd, een uiteinde in elke hand","Trek je ellebogen omlaag en naar achteren tot je handen op borsthoogte zijn","Laat de band gecontroleerd helemaal terug omhoog gaan"]'), '$.cues_nl', json('["Leid met je ellebogen, niet met je handen","Trek je schouderbladen omlaag en naar elkaar toe","💡 Schiet de band snel terug, ga dan dichter bij het ankerpunt staan"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-lat-pulldown' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Anchor a band above head height — a door anchor or closed door hinge works.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Doe de band net boven je knieën. Sta in een halve squat met je voeten op heupbreedte — er staat steeds spanning op de band","Stap met je rechtervoet naar rechts en haal je linkervoet bij tot je weer op heupbreedte staat. Laat je voeten elkaar niet raken","Loop het opgegeven aantal stappen één kant op en blijf even diep in je squat, ga dan terug"]'), '$.cues_nl', json('["💡 In de squat blijven ís de oefening — zodra je rechtop komt, stopt het werk voor je bilspieren helemaal","Voel de buitenkant van je heup aanspannen als je uitstapt. Dat is de gluteus medius — een spier die bepalend is voor de stabiliteit van je knie en heup"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-lateral-walk' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Place the band just above your knees. Stand in a half-squat position with feet hip-width — there should be constant tension in the band.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op het midden van de band staan, voeten op schouderbreedte. Houd de uiteinden op schouderhoogte, ellebogen naar voren. Zet spanning op de band voordat je begint","Druk omhoog tot je armen helemaal gestrekt zijn. Core aangespannen — laat je onderrug niet hol trekken als je armen omhooggaan","Zak langzaam terug naar schouderhoogte en houd de band de hele weg onder controle"]'), '$.cues_nl', json('["💡 De band wordt zwaarder naarmate hij uitrekt — het bovenste deel van de press is het zwaarst, anders dan bij losse gewichten","Houd je ribben de hele tijd omlaag. Boven je hoofd drukken legt een zwakke onderrug snel bloot"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-overhead-press' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand on the center of the band with feet shoulder-width. Hold the ends at shoulder height, elbows forward. Create tension in the band before starting.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Anchor a band at chest height. Stand side-on, both hands on the band at your sternum.","Step out until the band is taut.","Press your hands straight out in front of you and hold — the band will try to rotate you.","Return to the chest. Complete the reps, then change sides."]'), '$.cues', json('["Do not let your torso twist — that is the whole exercise","Squeeze the glutes to stop the hips rotating","💡 Resisting the pull trains your core to stay steady when a force tries to turn you"]'), '$.steps_nl', json('["Maak een band vast op borsthoogte. Ga er zijwaarts naast staan met beide handen aan de band bij je borstbeen","Stap opzij tot de band strak staat","Druk je handen recht voor je uit en houd vast — de band probeert je te draaien","Breng je handen terug naar je borst. Doe alle herhalingen en wissel dan van kant"]'), '$.cues_nl', json('["Laat je romp niet draaien — dat is de hele oefening","Span je bilspieren aan zodat je heupen niet meedraaien","💡 Weerstand bieden tegen de trek leert je core stabiel te blijven als een kracht je wil laten draaien"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-pallof-press' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Anchor a band at chest height. Stand side-on, both hands on the band at your sternum.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Houd de band met beide handen op schouderbreedte voor je vast, op schouderhoogte en met gestrekte armen","Trek de band uit elkaar door je armen zijwaarts te bewegen tot hij je borst raakt","Ga langzaam terug — bied weerstand als de band je handen weer naar elkaar trekt"]'), '$.cues_nl', json('["💡 Ideaal als warming-up of tussen sets drukoefeningen om je schouder in balans te houden","Houd de beweging gecontroleerd — een slappe band betekent geen spanning"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-pull-apart' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Hold the band with both hands shoulder-width apart in front of you at shoulder height, arms straight.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op de vloer zitten met gestrekte benen. Leg de band om je voeten of om een vast ankerpunt. Houd beide uiteinden vast met gestrekte armen en een rechte rug","Trek je ellebogen naar achteren en knijp je schouderbladen naar elkaar. Breng je handen naar je onderste ribben","Ga gecontroleerd terug — bied weerstand als de band je naar voren trekt. Maak je rug niet bol op de terugweg"]'), '$.cues_nl', json('["💡 Blijf de hele tijd rechtop zitten — bij een bolle rug verschuift de belasting van je lats naar je onderrug","Houd een volle seconde vast op het punt van maximale aanspanning voordat je loslaat. In die pauze wordt de spier opgebouwd"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-row-seated' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Sit on the floor with legs extended. Loop the band around your feet or a fixed anchor. Hold both ends with arms extended, back tall.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op de vloer zitten met gestrekte benen en de band om beide voeten","Zit rechtop met een lange rug en houd in elke hand een uiteinde vast","Trek je handen naar je taille, ellebogen dicht langs je lichaam","Strek je armen langzaam"]'), '$.cues_nl', json('["Borst de hele tijd omhoog","Leun niet achterover om de band te bewegen","💡 Buig je knieën licht als je hamstrings strak zijn"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-seated-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit on the floor, legs straight, band looped around both feet.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Maak een weerstandsband vast op taillehoogte, of ga op één uiteinde staan","Ga zijwaarts staan en houd de band in één hand, arm gestrekt","Trek je hand naar je ribben en houd je romp stil","Herhaal en wissel dan van kant"]'), '$.cues_nl', json('["Draai je romp niet mee om het trekken makkelijker te maken","Evenveel herhalingen aan beide kanten","💡 Laat het verschil tussen links en rechts zien dat een row met twee armen verbergt"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-single-arm-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Anchor a band at waist height, or stand on one end.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op het midden van de band staan, voeten op schouderbreedte. Houd de uiteinden op schouderhoogte of gekruist voor je borst","Zak in een squat — heupen naar achteren en omlaag, borst omhoog, knieën in lijn met je tenen. Zak minstens tot je bovenbenen horizontaal zijn","Duw door je hielen om te gaan staan en voel de weerstand van de band toenemen naarmate je hoger komt. Span bovenin je bilspieren aan"]'), '$.cues_nl', json('["💡 Een squat met band belast de top van de beweging anders dan losse gewichten — zo train je kracht in het laatste stuk en explosieve heupstrekking","Gebruik de spanning bovenin als seintje om je knieën naar buiten te duwen. De band geeft precies de feedback die je van een barbell krijgt"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-squat' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand on the center of the band with feet shoulder-width. Hold the ends at shoulder height or crossed over your chest.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Maak een band hoog vast. Ga zijwaarts staan met beide handen aan het uiteinde","Trek de band schuin voor je lichaam langs naar je andere heup en draai mee op je achterste voet","Ga gecontroleerd terug. Wissel van kant"]'), '$.cues_nl', json('["Draai vanuit je ribbenkast, niet alleen met je armen","Houd je armen vrijwel gestrekt","💡 Past goed bij de Pallof press: de ene traint rotatie, de andere weerstaat die"]')), updated_at_ms = 1795305600000 WHERE slug = 'band-wood-chop' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Anchor a band high. Stand side-on, both hands on the end.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Leg de stang in het rek op de hoogte van je bovenborst. Stap eronder en laat de stang op je bovenrug rusten — niet op je nek","Span je romp aan, til de stang uit het rek en doe twee stappen naar achteren","Zak naar achteren en omlaag tot je bovenbenen horizontaal zijn","Duw door je hele voet om te gaan staan"]'), '$.cues_nl', json('["Je knieën blijven in lijn met je tenen","Houd je borst trots vooruit als je uit het diepste punt komt","💡 Gebruik altijd de veiligheidspennen — zet ze net onder je laagste positie"]')), updated_at_ms = 1795305600000 WHERE slug = 'barbell-back-squat' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Set the bar at upper-chest height in the rack. Step under it, bar resting across your upper back — not your neck.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op de bank liggen met je ogen onder de stang en je voeten plat op de vloer","Pak de stang iets breder dan schouderbreedte vast en til hem uit het rek","Laat de stang zakken naar het midden van je borst, ellebogen zo''n 45° van je lichaam","Druk de stang weer omhoog"]'), '$.cues_nl', json('["Houd je schouderbladen de hele set samengeknepen tegen de bank","Polsen recht boven je ellebogen","💡 Druk nooit zwaar in je eentje zonder veiligheidsarmen of iemand die je helpt"]')), updated_at_ms = 1795305600000 WHERE slug = 'barbell-bench-press' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Lie on the bench, eyes under the bar, feet flat on the floor.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Pak de stang bovenhands vast, handen op schouderbreedte","Scharnier vanuit je heupen tot ongeveer 45°, met een vlakke rug en de stang hangend bij je schenen","Trek de stang naar je onderste ribben","Laat gecontroleerd zakken zonder je rug bol te maken"]'), '$.cues_nl', json('["De hoek van je romp blijft gelijk — row niet door overeind te komen","Trek je ellebogen naar achteren, niet naar buiten","💡 Lichter dan je denkt: je techniek gaat bij deze oefening snel achteruit"]')), updated_at_ms = 1795305600000 WHERE slug = 'barbell-bent-over-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Hold the bar with an overhand grip, hands shoulder-width.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Rest the bar on your upper back and stand tall, on a step if you have one","Rise onto the balls of your feet as high as you can","Pause at the top","Lower slowly until you feel a stretch"]'), '$.cues', json('["Slow on the way down — that is where the work is","Do not bounce","💡 Calf capacity is the main protector against running injuries"]'), '$.steps_nl', json('["Leg de stang op je bovenrug en sta rechtop, op een opstapje als je er een hebt","Kom zo hoog mogelijk omhoog op de bal van je voeten","Houd bovenin even vast","Zak langzaam tot je rek voelt"]'), '$.cues_nl', json('["Zak langzaam — daar zit het echte werk","Niet veren","💡 Sterke kuiten zijn de belangrijkste bescherming tegen hardloopblessures"]')), updated_at_ms = 1795305600000 WHERE slug = 'barbell-calf-raise' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Bar on your upper back, standing tall — on a step if you have one.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga staan met de stang boven het midden van je voeten, voeten op heupbreedte","Scharnier vanuit je heupen en pak de stang net buiten je benen vast; laat je heupen zakken tot je schenen de stang raken","Trek de speling uit de stang, span je romp aan en kom overeind door de vloer weg te duwen","Laat de stang zakken door je heupen naar achteren te brengen en houd hem dicht bij je"]'), '$.cues_nl', json('["Vlakke rug van het begin van de lift tot je helemaal rechtop staat","De stang blijft contact houden met je benen","💡 Stop de set zodra je rug bol wordt — dit is geen lift om doorheen te worstelen"]')), updated_at_ms = 1795305600000 WHERE slug = 'barbell-deadlift' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with the bar over your mid-foot, feet hip-width.';
