UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand with barbell (or weighted rucksack/box) over mid-foot, feet hip-width","Hinge at hips and grip object firmly","Brace core, keep back straight, press floor away to lift","Lock hips and knees fully at top","Lower with control"]'), '$.cues', json('["Do 3 sets of sustained effort with 30 s rest between sets","You can swap the barbell for a filled rucksack or a sturdy box","Keep a flat back throughout — do not round it"]'), '$.steps_nl', json('["Ga staan met de barbell (of een verzwaarde rugzak of doos) boven het midden van je voeten, voeten op heupbreedte","Scharnier vanuit je heupen en pak het voorwerp stevig vast","Span je core aan, houd je rug recht en duw de vloer weg om te tillen","Strek bovenin je heupen en knieën volledig","Laat gecontroleerd zakken"]'), '$.cues_nl', json('["Doe 3 sets met aanhoudende inspanning, met 30 s rust tussen de sets","Je kunt de barbell vervangen door een gevulde rugzak of een stevige doos","Houd je rug de hele tijd vlak — maak hem niet bol"]')), updated_at_ms = 1795305600000 WHERE slug = 'deadlift' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with barbell (or weighted rucksack/box) over mid-foot, feet hip-width';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Begin in push-uphouding met je handen dicht bij elkaar recht onder je borst — duimen en wijsvingers tegen elkaar, zodat ze een diamant of driehoek vormen","Span je core aan en laat je borst naar je handen zakken, met je ellebogen dicht langs je zij. Ze strijken onderweg langs je ribben en wijzen niet naar buiten","Druk jezelf terug omhoog tot je armen gestrekt zijn en span bovenin je triceps hard aan","Blijf de hele tijd een strakke plank — heupen recht, niet doorzakken in je middel en je billen niet omhoog steken"]'), '$.cues_nl', json('["Je triceps doen hier het meeste werk — zie dit als een tricepsoefening die ook je borst belast","Je ellebogen blijven de hele tijd dicht bij je ribben — wijzen ze naar buiten, dan verlies je de nadruk op je triceps","💡 💡 Beginner: zet je handen op een stoel om het lichter te maken. Gevorderd: zak in 3 seconden gecontroleerd voor maximale tijd onder spanning"]')), updated_at_ms = 1795305600000 WHERE slug = 'diamond-push-up' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Start in a push-up position with your hands close together directly beneath your chest — thumbs and index fingers touching to form a diamond or triangle shape.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Pak de stangen van de brug vast en druk jezelf op tot je armen gestrekt zijn","Zak tot je bovenarmen ongeveer horizontaal zijn","Druk jezelf terug omhoog"]'), '$.cues_nl', json('["Leun iets naar voren voor je borst, blijf rechtop voor je triceps","Zak niet dieper dan prettig is voor je schouders","💡 Stop de set ruim voordat je schouders gaan zeuren"]')), updated_at_ms = 1795305600000 WHERE slug = 'dip-station-dip' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Grip the parallel bars and press up to straight arms.';
