UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga met je gezicht naar een deurpost staan, je voeten aan weerszijden ervan","Pak beide kanten op borsthoogte vast, strek je armen en leun naar achteren","Trek jezelf naar de deurpost toe en houd vast, met je schouderbladen samengeknepen","Houd vast en laat dan langzaam los"]'), '$.cues_nl', json('["Je lichaam blijft één rechte lijn van hiel tot hoofd","Adem door terwijl je vasthoudt","💡 De eenvoudigste manier om trekken te trainen zonder enig materiaal"]')), updated_at_ms = 1795305600000 WHERE slug = 'doorway-isometric-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand facing a door frame, feet either side of it.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zit of sta met twee dumbbells op schouderhoogte, handpalmen naar je gezicht — alsof je net een biceps curl hebt afgemaakt","Druk de gewichten omhoog en draai je handpalmen daarbij naar voren. Eindig met je armen volledig gestrekt boven je hoofd","Andersom terug: laat zakken naar de beginpositie en draai je handpalmen weer naar je gezicht. Dat is één herhaling"]'), '$.cues_nl', json('["💡 Om de draai gaat het: die zet alle drie de koppen van je schouderspier aan het werk, niet alleen de voorste zoals bij een gewone press","Span bovenin je core aan. Maak je onderrug niet hol als de dumbbells helemaal boven zijn"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-arnold-press' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Sit or stand holding two dumbbells at shoulder height, palms facing your face — as if you just finished a bicep curl.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta met je voeten op schouderbreedte en scharnier vanuit je heupen tot je romp bijna horizontaal is, knieën licht gebogen. Houd beide dumbbells vast met je handpalmen naar elkaar toe","Trek beide dumbbells tegelijk naar je onderste ribben en stuur je ellebogen naar achteren. Span bovenin je bovenrug hard aan","Laat volledig gecontroleerd zakken — laat de zwaartekracht het zakken niet overnemen"]'), '$.cues_nl', json('["💡 Je onderrug staat de hele tijd statisch onder spanning — span je core aan voor elke herhaling","Ga je veren of rukken, dan is het gewicht te zwaar. Met gecontroleerde rows bouw je meer spier op"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-bent-over-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with feet shoulder-width, hinge at the hips until your torso is near parallel to the floor, knees soft. Hold both dumbbells with a neutral grip.';
