UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga voor een bank of stoel staan. Leg je achterste voet erop, wreef naar beneden. Houd in elke hand een dumbbell. Zet je voorste voet zo ver naar voren dat je scheen bijna verticaal blijft als je zakt","Laat je achterste knie richting de vloer zakken door je voorste knie te buigen. Houd je romp de hele tijd rechtop — leun niet naar voren","Duw door je voorste hiel omhoog tot je heup volledig gestrekt is. Dat is één herhaling. Doe alle herhalingen aan één kant voordat je wisselt"]'), '$.cues_nl', json('["💡 Je voelt het werk vooral in de bilspier en het bovenbeen van je voorste been. Voel je het vooral in je knie, zet je voorste voet dan verder naar voren","Dit is net zo goed een balansoefening als een krachtoefening — houd het licht tot je de houding beheerst"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-bulgarian-split-squat' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand in front of a bench or chair. Place your rear foot on it, laces down. Hold a dumbbell in each hand. Step your front foot forward far enough that your shin stays close to vertical when you descend.';
