UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga plat op de vloer liggen met de dumbbells boven je borst, handpalmen naar voren, bovenarmen rustend op de vloer","Laat de dumbbells zakken tot je bovenarmen de vloer raken en houd even vast. Houd je polsen de hele tijd recht boven je ellebogen","Druk explosief terug omhoog en stop net voordat je ellebogen helemaal gestrekt zijn, zodat de spanning op je borst blijft"]'), '$.cues_nl', json('["💡 Door de pauze onderin verdwijnt de opgeslagen veerkracht — elke herhaling begint vanuit stilstand, wat dit zwaarder en effectiever maakt dan een bench press","Houd je onderrug de hele tijd plat op de vloer. Niet hol trekken"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-chest-press-floor' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Lie flat on the floor holding dumbbells above your chest, palms facing forward, upper arms resting on the floor.';
