UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Houd één dumbbell verticaal voor je borst — beide handen om het bovenste uiteinde","Sta met je voeten op schouderbreedte, tenen 15–30° naar buiten. Zak in een squat en houd de dumbbell dicht bij je borst","Duw door je hielen om te gaan staan en span bovenin je bilspieren aan"]'), '$.cues_nl', json('["💡 Je borst blijft omhoog — het gewicht is een tegenwicht waarmee je diep kunt zakken","Je knieën blijven de hele tijd in lijn met je tenen — duw ze naar buiten als ze naar binnen vallen"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-goblet-squat' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Hold one dumbbell vertically at your chest — both hands cupping the top end.';
