UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga op de vloer zitten met je bovenrug tegen een bank, schouderbladen op de rand. Leg een dumbbell dwars over je heupen. Voeten plat, op heupbreedte","Duw door je hielen om je heupen omhoog te brengen tot je lichaam een rechte lijn vormt van knieën tot schouders. Span bovenin je bilspieren hard aan","Laat je heupen gecontroleerd terugzakken richting de vloer. Dat is één herhaling"]'), '$.cues_nl', json('["💡 Het aanspannen van je bilspieren bovenin ís de oefening — half aanspannen levert de helft op","Trek je kin iets in en span je core aan, zodat je je onderrug niet overstrekt"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-hip-thrust' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Sit on the floor with your upper back against a bench, shoulder blades on the edge. Place a dumbbell horizontally across your hips. Feet flat, hip-width apart.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga schuin achterover zitten (op de armleuning van de bank, tegen een muur of op een schuin oppervlak)","Houd de dumbbells op borsthoogte, handpalmen naar voren","Druk de dumbbells omhoog en iets naar binnen tot je armen bijna gestrekt zijn","Laat langzaam zakken naar de beginpositie"]'), '$.cues_nl', json('["Schuin drukken traint het bovenste deel van je borst","Voor veel mensen prettiger dan plat drukken","Druk na 16 weken zwangerschap niet meer plat op je rug"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-incline-chest-press' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit at an incline (on sofa arm, against wall, or on inclined surface)';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta met je voeten op heupbreedte en houd in elke hand een dumbbell langs je zij. Til beide dumbbells zijwaarts op tot je armen horizontaal zijn, met je ellebogen iets voorop","Houd bovenin even vast — laat het gewicht niet op vaart omhoogkomen. Je handpalmen wijzen bovenin naar beneden","Laat langzaam zakken — 3 seconden omlaag. Het zakken traint de achterste en zijkant van je schouderspier veel meer dan het optillen"]'), '$.cues_nl', json('["💡 Lichter dan je denkt — met zwaar gewicht wordt zijwaarts heffen een schouderophaalbeweging. Kies een gewicht dat je volledig onder controle hebt","Licht voorover leunen (10–15 graden) legt meer belasting op de zijkant van je schouder en minder op je monnikskapspier"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-lateral-raise' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with feet hip-width holding a dumbbell in each hand at your sides. Raise both dumbbells out to the sides until your arms are parallel to the floor, leading with your elbows slightly.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop met dumbbells langs je zij","Stap met je rechtervoet naar voren en laat je achterste knie richting de vloer zakken","Duw door je voorste voet om terug te komen","Wissel van been"]'), '$.cues_nl', json('["Houd je voorste knie boven je enkel","Blijf rechtop","De dumbbells maken de uitvalspas zwaarder dan met alleen lichaamsgewicht"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-lunge' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand holding dumbbells at sides';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Houd één dumbbell met beide handen boven je hoofd","Buig je ellebogen en laat de dumbbell achter je hoofd zakken","Strek je armen om terug te komen","Houd je ellebogen naar voren gericht"]'), '$.cues_nl', json('["Je ellebogen blijven dicht bij je hoofd","Zak gecontroleerd","Houd je core aangespannen"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-overhead-tricep-ext' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Hold one dumbbell with both hands overhead';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Hold a dumbbell in each hand and hinge forward at the hips to 45°, or sit and hinge over your thighs","Let your arms hang straight down with a slight bend in the elbows","Raise your arms out to the sides to shoulder height","Squeeze your shoulder blades together at the top","Lower the dumbbells slowly to the start"]'), '$.cues', json('["Lead with elbows","Light weight — this is harder than it looks","Great for counteracting forward shoulder roll in pregnancy"]'), '$.steps_nl', json('["Pak in elke hand een dumbbell en scharnier vanuit je heupen 45° naar voren, of ga zitten en buig over je bovenbenen","Laat je armen recht naar beneden hangen met licht gebogen ellebogen","Til je armen zijwaarts op tot schouderhoogte","Knijp bovenin je schouderbladen samen","Laat de dumbbells langzaam terugzakken naar de start"]'), '$.cues_nl', json('["Leid met je ellebogen","Licht gewicht — dit is zwaarder dan het lijkt","Goed tegenwicht voor schouders die tijdens de zwangerschap naar voren trekken"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-rear-delt-fly' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 5 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Hinge forward at hips 45° or sit and hinge over thighs';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga in een hoge plank staan met een dumbbell onder elke hand. Zet je voeten breder dan heupbreedte voor stabiliteit. Je lichaam vormt een rechte lijn van hoofd tot hielen","Trek één dumbbell naar je heup en druk de andere in de vloer. Houd je heupen helemaal recht — draai of kantel niet mee","Zet de dumbbell terug op de vloer en doe dan de row aan de andere kant. Beide kanten samen is één herhaling"]'), '$.cues_nl', json('["💡 Het tegengaan van de draaiing is hier de echte oefening. Wiebelt je heup, dan is je core de beperkende factor, niet je rug","Pak lichter dan je denkt. Dit is geen zware row — het is een plank met een row erbij"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-renegade-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Get into a high plank with a dumbbell under each hand. Feet wider than hip-width for stability. Body forms a straight line from head to heels.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop met de dumbbells in een bovenhandse greep (handpalmen naar beneden), armen volledig gestrekt langs je lichaam","Curl beide dumbbells naar je schouders en houd je ellebogen vast tegen je zij. Met de handpalmen naar beneden werken je brachialis en onderarmen harder dan bij een gewone curl","Laat langzaam zakken — de weg terug is met een bovenhandse greep pittig. Strek je armen tussen elke herhaling volledig"]'), '$.cues_nl', json('["💡 Minder sterk dan bij een gewone curl? Mooi — dan heb je een echte zwakke schakel gevonden. Dit geeft je onderarmen de dikte die de meeste mensen verwaarlozen","Houd je polsen recht — laat ze tijdens de curl niet naar binnen krullen"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-reverse-curl' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall holding dumbbells with an overhand grip (palms facing down), arms fully extended at your sides.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand tall holding the dumbbells in front of your thighs, palms facing you","Hinge at the hips, sending them back, and lower the weights along your legs","Stop when you feel a stretch in your hamstrings (shin level for most)","Drive your hips forward to stand up and squeeze your glutes at the top"]'), '$.cues', json('["Keep dumbbells close to legs","Neutral spine throughout","Lighter load appropriate during pregnancy"]'), '$.steps_nl', json('["Sta rechtop met de dumbbells voor je bovenbenen, handpalmen naar je toe","Scharnier vanuit je heupen, duw ze naar achteren en laat de gewichten langs je benen zakken","Stop zodra je rek voelt in je hamstrings (voor de meesten op scheenhoogte)","Duw je heupen naar voren om rechtop te komen en span bovenin je bilspieren aan"]'), '$.cues_nl', json('["Houd de dumbbells dicht bij je benen","Houd je rug de hele beweging neutraal","Kies tijdens de zwangerschap een lichter gewicht"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-romanian-deadlift' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand, dumbbells in front of thighs, palms facing you';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta met je voeten op heupbreedte en scharnier 45° naar voren met een vlakke rug. Houd in elke hand een dumbbell, armen recht naar beneden","Trek je ellebogen naar achteren richting je heupen en breng de dumbbells naar je onderste ribben. Knijp bovenin je schouderbladen samen","Laat gecontroleerd zakken — laat het gewicht je schouders niet naar voren trekken"]'), '$.cues_nl', json('["💡 Eerst scharnieren, dan trekken — zet je rug vlak voordat je iets optrekt","Denk: ellebogen naar je achterzakken, niet handen naar je borst. Je elleboog leidt de beweging"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with feet hip-width, hinge forward 45° keeping your back flat. Hold a dumbbell in each hand, arms hanging straight down.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga rechtop op een stevige stoel zitten met de dumbbells op schouderhoogte, handpalmen naar voren","Druk de dumbbells boven je hoofd tot je armen bijna gestrekt zijn","Laat gecontroleerd zakken"]'), '$.cues_nl', json('["Zittend ontlast je je onderrug","Maak bovenin geen holle rug","Veilig alternatief voor de staande press tijdens de zwangerschap"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-seated-overhead-press' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit upright on a sturdy chair, dumbbells at shoulder height, palms forward';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Ga zitten of staan met de dumbbells op schouderhoogte, handpalmen naar voren. Je ellebogen staan in ongeveer 90 graden en net onder oorhoogte — niet te laag en niet te ver omhoog","Druk beide dumbbells recht boven je hoofd tot je armen volledig gestrekt zijn. Adem uit op de weg omhoog. Zet je ellebogen bovenin niet hard op slot","Laat langzaam en gecontroleerd zakken naar de startpositie, ellebogen terug naar 90 graden. Adem in op de weg omlaag","Houd je core de hele tijd stevig aangespannen — maak geen holle onderrug als het gewicht boven je hoofd komt"]'), '$.cues_nl', json('["Houd je polsen de hele tijd recht boven je ellebogen — polsen die naar achteren knikken vergroten de kans op blessures en kosten kracht","Voel je iets knellen aan de voorkant van je schouder, probeer dan een neutrale greep (handpalmen naar elkaar) — je schouder draait dan naar buiten in een veiligere positie","💡 💡 Zittend kun je je benen niet gebruiken, dus je schouders doen al het werk. Staand vraagt het stabiliteit van je hele lichaam"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-shoulder-press' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Sit or stand with dumbbells at shoulder height, palms facing forward. Elbows should be at roughly 90 degrees and just below the level of your ears — not dropped too low or flared too high.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop met de dumbbells langs je lichaam","Trek je schouders recht omhoog richting je oren","Houd bovenin 1 seconde vast","Laat langzaam zakken"]'), '$.cues_nl', json('["Rol niet met je schouders — recht omhoog en omlaag","Span bovenin je monnikskapspier aan","Helpt bij spanning in je bovenrug door tillen en dragen"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-shrug' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand holding dumbbells at sides';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop met een dumbbell langs je lichaam. Stap breed opzij en houd de tenen van beide voeten naar voren of iets naar buiten","Buig de knie van het been waarmee je stapt en zak in die heup. Houd je andere been gestrekt. Laat de dumbbell naast je gebogen knie hangen","Duw je af met je gebogen been om weer rechtop te komen. Doe alle herhalingen aan één kant en wissel dan"]'), '$.cues_nl', json('["💡 De zijwaartse beweging vraagt kracht in je heupabductoren en een soepele binnenkant van je bovenbenen — twee dingen die in de meeste trainingsschema''s ontbreken","Houd je rug vlak en je borst omhoog terwijl je in de uitvalspas zakt. Buig je voorover, dan is het gewicht te zwaar"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-side-lunge' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall holding a dumbbell at your side. Step wide out to one side, keeping toes pointing forward or slightly out on both feet.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Step your left foot forward, hinge forward with a flat back and rest your left hand on your left thigh","Hold the dumbbell in your right hand with your arm hanging straight below your shoulder","Row the dumbbell to your hip, keeping your elbow close to your torso","Stop when your upper arm is roughly parallel to the floor","Lower slowly until your arm is fully extended","Complete all reps, then switch sides"]'), '$.cues', json('["💡 Keep your working shoulder level — do not let it rotate up to help the lift.","Elbow to pocket, not elbow to ceiling. The lat does the pulling, not the shoulder."]'), '$.steps_nl', json('["Zet je linkervoet naar voren, scharnier met een vlakke rug naar voren en steun met je linkerhand op je linkerbovenbeen","Houd de dumbbell in je rechterhand en laat je arm recht onder je schouder hangen","Trek de dumbbell naar je heup en houd je elleboog dicht bij je romp","Stop als je bovenarm ongeveer horizontaal is","Laat langzaam zakken tot je arm volledig gestrekt is","Doe alle herhalingen en wissel dan van kant"]'), '$.cues_nl', json('["💡 Houd je werkende schouder recht — laat hem niet omhoog draaien om mee te helpen","Elleboog naar je broekzak, niet naar het plafond. Je brede rugspier trekt, niet je schouder"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-single-arm-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Place your left hand and left knee on a bench for support. Hold the dumbbell in your right hand, arm hanging straight below your shoulder.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop met een dumbbell in één of beide handen. Breng je gewicht naar één been en houd die knie licht gebogen","Scharnier vanuit je heup naar voren en laat de dumbbell langs je standbeen zakken terwijl je andere been naar achteren strekt. Houd je heupen recht — draai niet mee","Kom terug omhoog door via je hiel te duwen en span bovenin je bilspier aan. Dat is één herhaling"]'), '$.cues_nl', json('["💡 Zie je achterste been en je romp als één stijve plank — ze bewegen samen, niet los van elkaar","De beweging eindigt waar je heup begint te draaien. Ga niet dieper ten koste van een recht bekken"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-single-leg-rdl' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall holding a dumbbell in one or both hands. Shift your weight onto one leg, keeping a soft bend in that knee.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Houd één dumbbell in één hand langs je lichaam — zoals een koffer. Sta rechtop met je schouders op gelijke hoogte","Loop vooruit voor de opgegeven afstand of tijd en buig niet opzij naar het gewicht. Houd je core aangespannen, kijk vooruit en adem rustig door","Wissel halverwege van hand en loop terug"]'), '$.cues_nl', json('["💡 De uitdaging is niet opzij te hellen — zodra je naar het gewicht kantelt, heeft je core het verloren","Langzaam en zwaar wint van snel en licht. Dragen met gewicht is een oefening in houding en aanspannen, geen conditiesprint"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-suitcase-carry' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Hold a single dumbbell in one hand at your side — suitcase style. Stand tall with shoulders level and equal.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand with your feet wide and toes turned out 45°, holding one dumbbell vertically between your legs","Hinge at the hips and bend your knees to lower the weight toward the floor","Drive through your heels and hips to stand up","Squeeze your glutes at the top"]'), '$.cues', json('["Keeps weight between legs — great for pregnancy","Chest stays tall","Sumo stance gives belly room"]'), '$.steps_nl', json('["Sta met je voeten wijd en je tenen 45° naar buiten, en houd één dumbbell verticaal tussen je benen","Scharnier vanuit je heupen en buig je knieën om het gewicht richting de vloer te laten zakken","Duw via je hielen en heupen omhoog tot je staat","Span bovenin je bilspieren aan"]'), '$.cues_nl', json('["Het gewicht blijft tussen je benen — fijn tijdens de zwangerschap","Houd je borst omhoog","De sumostand geeft je buik de ruimte"]')), updated_at_ms = 1795305600000 WHERE slug = 'dumbbell-sumo-deadlift' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Stand feet wide, toes turned out 45°, hold dumbbell vertically between legs';
