UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Houd een dumbbell verticaal op borsthoogte, beide handen om het bovenste uiteinde, ellebogen naar beneden. Sta met je voeten op schouderbreedte, tenen 15–30 graden naar buiten","Adem in. Duw je heupen naar achteren en buig je knieën tot je bovenbenen horizontaal zijn of dieper. Houd de dumbbell de hele tijd dicht bij je borst","Onderin mogen je ellebogen licht tegen de binnenkant van je knieën drukken — zo blijven je knieën naar buiten boven je tenen","Duw via je hielen omhoog. Span bovenin je bilspieren stevig aan en adem uit. Herhaal"]'), '$.cues_nl', json('["Het gewicht voor je werkt als tegenwicht — gebruik het om dieper te zakken dan bij een gewone squat","Je borst blijft de hele weg omlaag en omhoog rechtop. Trekt de dumbbell je naar voren, pak dan lichter","💡 💡 Beginner: zak alleen zo diep als je met een vlakke rug kunt. Gevorderd: pauzeer 2 seconden onderin voordat je omhoog duwt"]')), updated_at_ms = 1795305600000 WHERE slug = 'goblet-squat' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Hold a dumbbell vertically at chest height, both hands cupping the top end, elbows pointing down. Stand with feet shoulder-width apart, toes turned out 15-30 degrees.';
