UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Houd de kettlebell verticaal tegen je borst met beide handen om de bovenkant van de bol. Sta met je voeten op schouderbreedte, tenen 15 tot 30 graden naar buiten","Zak in de squat met de kettlebell dicht bij je borst — het gewicht werkt als tegenwicht en trekt je in een diepe, rechte houding","Duw via je hielen omhoog en span bovenin je bilspieren aan. Dat is één herhaling"]'), '$.cues_nl', json('["💡 De gobletpositie dwingt een rechte romp en diepe heupbuiging af — een van de beste manieren om een goede squat aan te leren","Je knieën blijven de hele tijd boven je tenen. Vallen ze naar binnen, duw ze dan op de weg omlaag met je ellebogen naar buiten"]')), updated_at_ms = 1795305600000 WHERE slug = 'kettlebell-goblet-squat' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Hold the kettlebell vertically with both hands cupping the top of the bell at your chest. Stand with feet shoulder-width, toes angled out 15 to 30 degrees.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Houd de kettlebell met beide handen op borsthoogte, armen licht gebogen. Sta met je voeten op schouderbreedte","Beweeg de kettlebell in een cirkel om je hoofd: linkerkant, over de bovenkant, rechterkant en terug naar de start. Houd de cirkel gecontroleerd en dicht bij je hoofd","Doe de opgegeven herhalingen en draai dan even vaak de andere kant op"]'), '$.cues_nl', json('["💡 De halo vraagt mobiliteit én stabiliteit van je schouders tegelijk — ga langzaam genoeg om die controle te voelen","Houd je core aangespannen en leun niet mee. Kantel je om de kettlebell te volgen, ga dan langzamer"]')), updated_at_ms = 1795305600000 WHERE slug = 'kettlebell-halo' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Hold the kettlebell with both hands at chest height, arms slightly bent. Stand with feet shoulder-width.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta klaar zoals bij een swing, met de kettlebell naar achteren gezwaaid","Duw je heupen naar voren en trek je elleboog hoog en wijd terwijl de kettlebell omhoogkomt","Laat hem terugvallen in het heupscharnier"]'), '$.cues_nl', json('["Je elleboog leidt en blijft boven je pols","Je heupen doen het werk; je arm stuurt alleen","💡 De brug tussen een swing en een snatch"]')), updated_at_ms = 1795305600000 WHERE slug = 'kettlebell-high-pull' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Set up as for a swing, bell hiked back.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Hold the kettlebell in one hand, hinge forward with a flat back and rest your free hand on your thigh","Let the bell hang straight down, then row it to your ribs","Lower under control","Change sides after your reps"]'), '$.cues', json('["Do not rotate the torso to lift it higher","Elbow brushes past your side","💡 Pull your elbow towards your hip, not straight up, so your back does the work and not your arm"]'), '$.steps_nl', json('["Houd de kettlebell in één hand, scharnier met een vlakke rug naar voren en steun met je vrije hand op je bovenbeen","Laat de kettlebell recht naar beneden hangen en trek hem dan naar je ribben","Laat gecontroleerd zakken","Wissel na je herhalingen van kant"]'), '$.cues_nl', json('["Draai je romp niet mee om hem hoger te krijgen","Je elleboog strijkt langs je zij","💡 Trek je elleboog naar je heup, niet recht omhoog, zodat je rug het werk doet en niet je arm"]')), updated_at_ms = 1795305600000 WHERE slug = 'kettlebell-row' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Hinge forward with a flat back, one hand supported on a chair.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Breng de kettlebell met een clean naar de rackpositie: de bol rust op je onderarm, elleboog dicht bij je lichaam, pols recht, vuist op schouderhoogte","Druk recht omhoog tot je arm volledig gestrekt boven je hoofd is. Houd je core aangespannen en buig niet opzij","Laat de kettlebell gecontroleerd terugzakken naar de rackpositie. Doe alle herhalingen en wissel dan van kant"]'), '$.cues_nl', json('["💡 De rackpositie is een vaardigheid op zich — de kettlebell rust op je onderarm en hangt niet aan je pols","Een press met één arm laat elk verschil tussen links en rechts meteen zien. Begin met je zwakste arm"]')), updated_at_ms = 1795305600000 WHERE slug = 'kettlebell-single-arm-press' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Clean the kettlebell to the rack position: bell resting on your forearm, elbow close to your body, wrist neutral, fist at shoulder height.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Sta rechtop met de kettlebell in één hand langs je lichaam. Breng je gewicht naar het andere been, knie licht gebogen","Scharnier vanuit je heup en laat de kettlebell langs je standbeen zakken terwijl je andere been naar achteren strekt. Je heupen blijven recht","Kom terug omhoog door via je hiel te duwen en je bilspier aan te spannen. Dat is één herhaling. Doe alle herhalingen en wissel dan van kant"]'), '$.cues_nl', json('["💡 Zie je achterste been en je romp als één stijve plank — ze draaien als één geheel om je heupgewricht","De beweging eindigt waar je bekken gaat draaien. Kwaliteit boven diepte: een rechte heup op 45 graden is beter dan een gedraaide heup op 90"]')), updated_at_ms = 1795305600000 WHERE slug = 'kettlebell-single-leg-rdl' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 3 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 2 AND json_extract(instructions_json, '$.steps[0]') = 'Stand tall holding the kettlebell in one hand at your side. Shift your weight to the opposite leg, soft bend in the knee.';
UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps_nl', json('["Zwaai de kettlebell naar achteren tussen je benen","Duw je heupen krachtig naar voren en trek de kettlebell dicht langs je lichaam omhoog","Stoot je hand bovenin door, zodat de kettlebell rustig landt en niet omklapt","Laat gecontroleerd terugzakken in het heupscharnier"]'), '$.cues_nl', json('["De kracht komt uit je heupen, niet uit je arm","Bouw rustig op — te snel is dit zwaar voor je schouder","💡 Leer eerst de clean en de high pull"]')), updated_at_ms = 1795305600000 WHERE slug = 'kettlebell-snatch' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 3 AND json_extract(instructions_json, '$.steps[0]') = 'Hike the bell back between your legs.';
