UPDATE exercises SET instructions_json = json_set(instructions_json, '$.steps', json('["Stand with feet shoulder-width apart over the object (rucksack, crate, or box)","Hinge at hips and knees with flat back and grip the object firmly","Lift the object explosively from floor to hip height","Lower with control back to the floor"]'), '$.cues', json('["Do 3 sets of 30 s with 30 s rest between sets","Keep back straight throughout","Object: filled rucksack, crate, or box — test standard uses a munitiekist (20 kg Basis/K1, 30 kg K2-K6, 40 kg K3/K5/K6)"]'), '$.steps_nl', json('["Sta met je voeten op schouderbreedte boven het voorwerp (rugzak, krat of doos)","Buig vanuit je heupen en knieën met een rechte rug en pak het voorwerp stevig vast","Til het voorwerp explosief van de vloer tot heuphoogte","Laat het gecontroleerd terugzakken naar de vloer"]'), '$.cues_nl', json('["Doe 3 sets van 30 s met 30 s rust tussen de sets","Houd je rug de hele tijd recht","Voorwerp: gevulde rugzak, krat of doos — bij de test wordt een munitiekist gebruikt (20 kg Basis/K1, 30 kg K2-K6, 40 kg K3/K5/K6)"]')), updated_at_ms = 1795305600000 WHERE slug = 'optillen-vanaf-de-grond' AND gym_id IS NULL AND is_active = 1 AND json_valid(instructions_json) AND json_array_length(instructions_json, '$.steps') = 4 AND COALESCE(json_array_length(instructions_json, '$.cues'), 0) = 4 AND json_extract(instructions_json, '$.steps[0]') = 'Stand with feet shoulder-width apart over the object (rucksack, crate, or box)';
